(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-q-vdit-towards-accurate-quantization-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-1\">一 · 一个真实的服务现场：首帧返回被采样步数拖死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-2\">二 · 旧方案一：全精度多步采样是默认基线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-3\">三 · 旧方案二：常规低比特量化，权重能压、激活压不动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-4\">四 · 旧方案三：步数蒸馏与量化各自为战</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-5\">五 · 为什么非改不可：三重代价在同一请求上叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-6\">六 · 旧方案留下的接口缺口：分块流式与量化误差的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-7\">七 · 在线短视频生成的显存墙：全精度多步采样为何撑不住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-8\">八 · 请求形态的构成：长度由帧数与分块数共同决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-9\">九 · 并发与批大小：激活显存是硬约束，不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-10\">十 · SLO 的两个时间尺度：首块时延与整段完成时延</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-11\">十一 · 长尾的三个来源与可核查的测量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-12\">十二 · 方案反过来限制负载：分块上限即准入控制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-13\">十三 · 容量标定的落地顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-14\">十四 · 分块流式解码把负载从“请求级”改写成“块级”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-15\">十五 · 伪量化算子的数值解剖：clip、尺度与反量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-16\">十六 · 累加精度：低比特乘、高精度加的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-17\">十七 · Blackwell 数据通路：tcgen05、TMEM 与 2-SM MMA</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-18\">十八 · 数据类型谱系：FP16/BF16 到 FP8 到 NVFP4 的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-19\">十九 · 量化误差与蒸馏损失的耦合：公式逐项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-20\">二十 · 工程判断：精度档位与分块形状的联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-21\">二十一 · 显存账本的三层结构与可复算预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-22\">二十二 · 分页与分块：把峰值显存从“全序列”压到“块+重叠”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-23\">二十三 · 压缩与复用：量化尺度的时间维语义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-24\">二十四 · 卸载：VAE 与条件编码器的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-25\">二十五 · 带宽瓶颈的位置与 HBM3e 容量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-26\">二十六 · 失败模式与标定清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-27\">二十七 · 分块流式解码下的显存账本与带宽瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-28\">二十八 · 从“逐块去噪”到可调度的工作单元</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-29\">二十九 · chunked prefill 在视频 DiT 里的对应物</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-30\">三十 · 优先级、抢占与尾延迟的压缩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-31\">三十一 · 分离式预填/解码在分块流式里的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-32\">三十二 · 时延与吞吐的取舍线画在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-33\">三十三 · 分块流式下的调度边界：为什么这套方案没有连续批处理的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-34\">三十四 · 并行拓扑的切分维度与视频 DiT 的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-35\">三十五 · NVLink 5 与 NVSwitch：集合通信的物理底座</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-36\">三十六 · All-to-All 与 All-Reduce 的代价分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-37\">三十七 · NIXL 传输：分离式预填/解码与块级流式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-38\">三十八 · 通信成为瓶颈的判据与容量标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-39\">三十九 · 分块流式推理下的并行拓扑边界：通信何时压过计算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-40\">四十 · 精度塌陷的三种形态与量化误差的时间维指纹</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-41\">四十一 · OOM 与分块溢出回退：峰值显存的账怎么算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-42\">四十二 · 批抖动与尾延迟：少步调度下的方差来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-43\">四十三 · 静默降级：没有报错的质量衰减怎么抓</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-44\">四十四 · 回滚策略：按失败模式分层，而不是整段重跑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-45\">四十五 · 分块流式链路上的失效面：从量化溢出到静默降级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-46\">四十六 · 口径先于数字：这份材料能支撑什么判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-47\">四十七 · 硬件档位：Blackwell 上的低比特算子可用性决定基线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-48\">四十八 · batch 与并发：视频请求的批维度不是标量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-49\">四十九 · 指标怎么读：四条不可比的提升</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-50\">五十 · 长视频与分块边界：误差累积的测量缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-51\">五十一 · 落地标定的最小测量集</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-52\">五十二 · 迁移到非视频 DiT 时的量化侧改写</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-53\">五十三 · 蒸馏侧的迁移边界：教师轨迹依赖采样器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-54\">五十四 · 分块流式解码的适用上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-55\">五十五 · 与批调度、分离式部署的不兼容点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-56\">五十六 · 规模上限与判断准则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-q-vdit-towards-accurate-quantization-2025-sec-57\">五十七 · 迁移与边界：哪些结构能吃下这套方案，哪些只会放大它的误差</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:584px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 584.1 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">文本与首帧条件编码后进入 latent 序列，按时间块切分为去噪单元</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">每个去噪单元内执行时空注意力，激活经时间一致性量化算子转为低比特后送入…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">学生网络以蒸馏后的少步调度执行去噪，教师中间潜变量仅离线用于监督</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">去噪完成的 latent 分块送入 VAE 解码，块间保留重叠以抑制接缝</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码结果按流式顺序输出，显存峰值由分块大小与 KV／激活缓存预算共同约束</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-1\">一 · 一个真实的服务现场：首帧返回被采样步数拖死</h3>\n<p>设想一个面向短视频平台的在线文生视频服务：用户提交文本与首帧条件，期望在数秒内看到前两秒的预览片段，整段十秒视频在后台继续流式补齐。前端体验由两个指标卡住——首块输出时延与整段完成时延。在 Blackwell 单机上，这类请求的推理链路是：条件编码 → latent 初始化 → 逐步去噪（每步一次完整的时空注意力加 MLP 前向）→ VAE 解码 → 分块输出。问题出在第二步与第三步之间：视频 DiT 的采样步数决定了前向次数，而每一次前向都要把整段 latent 的激活读进 SM 的寄存器与共享内存。时空注意力的激活规模随帧数线性增长，注意力矩阵本身随帧数的平方增长，于是“多步采样”与“长视频”两个维度相乘，直接把首块时延推到用户耐心之外。</p>\n<p>更具体地算一笔账：设帧数 <span>F</span>、每帧 token 数 <span>N</span>、隐藏维 <span>d</span>，单步时空注意力的激活元素量约为 <span>O(F·N·d)</span>，注意力分数矩阵为 <span>O(F·N²)</span> 量级（跨帧时间注意力再叠一层）。若采样步数为 <span>T</span>，则端到端前向的激活读写总量近似正比于 <span>T·F·N·d</span>。在 HBM 带宽成为瓶颈的档位上，这个乘积就是延迟的主项；而在显存一侧，峰值占用由同时在处理的块数与激活缓存共同决定，帧数一涨就触发分块回退。也就是说，旧方案的成本结构是“步数 × 帧数”的双重放大，而不是单点的算力不足。</p>\n<p>这就是 Q-VDiT 要处理的现场：不是“模型不够大”，而是“每一步都太贵、步数又太多”。本片段只谈这篇论文之前推理栈的主流做法与它们为何不够用；量化算子与蒸馏联合的具体机制留给后续片段。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-2\">二 · 旧方案一：全精度多步采样是默认基线</h3>\n<p>论文之前，视频 DiT 推理的默认做法是全精度（FP16/BF16）权重与激活，配一套固定的多步采样调度（如数十步的 DDIM 类确定性采样）。它的优点是数值上“什么都不用想”：激活不离群、时间维一致、VAE 解码接缝干净。代价则全部落在推理系统侧：每一步都要把整段 latent 的激活从 HBM 搬到片上，时空注意力在 SM 内完成后再写回；步数越多，HBM 往返次数越多。对于十秒级、较高分辨率的请求，激活缓存本身就吃掉相当比例的显存预算，批大小被迫压到很小，吞吐随并发上升而恶化。</p>\n<p>用伪代码描述这条链路的资源行为：</p>\n<div class=\"formula\">$$\\text{cost}_{\\text{step}} \\approx \\underbrace{F\\cdot N\\cdot d\\cdot b}_{\\text{激活读写}}+\\underbrace{F\\cdot N^2}_{\\text{注意力分数}},\\quad \\text{cost}_{\\text{e2e}} \\approx T\\cdot \\text{cost}_{\\text{step}}+\\text{cost}_{\\text{VAE}}$$</div>\n<p>其中 <span>b</span> 为字节数。可见降低 <span>T</span> 或压缩 <span>d</span> 的字节宽度都能线性削减主项。旧方案在这两个方向都没有动作，于是延迟与显存带宽压力成为结构性痛点：不是调参能解决的，必须改推理链本身。一个典型例子是：同一台 Blackwell 机器上，把批大小从 1 提到 4 时，激活缓存先于权重触及显存上限，服务端只能退回批 1 加串行排队，吞吐被锁死。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-3\">三 · 旧方案二：常规低比特量化，权重能压、激活压不动</h3>\n<p>第二类主流做法是把权重量化到低比特（INT8/FP8 乃至更低），激活保持较高精度，即 W4A16 或 W8A8 一类的非对称配置。这条路在 LLM 推理上成熟，原因是语言模型的激活分布相对温和，逐通道或分组尺度足以吸收离群值。但搬到视频 DiT 上就暴露出结构性缺陷：视频分支的激活离群值不是静态的，它沿时间维漂移——某些帧的注意力输入出现尖峰，下一帧又回落。固定的量化尺度要么裁掉尖峰（信息损失），要么放大步长（量化噪声淹没小值），两者都直接损伤生成质量。</p>\n<p>论文给出的问题陈述很直接：视频生成 DiT 在 W4A4 这类低比特激活量化下精度显著下降。原因被归为现有量化方法缺少对视频时空激活分布的时间一致性建模——尺度是按张量或按通道定的，没有把“跨帧的时间维”当作一个需要约束的轴。于是量化误差在时空注意力输入处被引入，并沿时间维逐步累积：第 <span>t</span> 帧的量化偏差进入注意力输出，污染第 <span>t+1</span> 帧的输入分布，误差像滚雪球一样在采样轨迹上放大。长视频场景下这种累积尤其危险，而材料明确指出未给出误差上界或补偿机制。</p>\n<p>系统代价上，W4A4 的诱惑在于把激活字节宽度压到 FP16 的四分之一，理论上把 <span>F·N·d·b</span> 主项砍掉大半，从而同时缓解带宽与显存。但精度崩塌使得这条收益无法兑现：工程上只能退回 W8A8 或权重-only 量化，带宽收益打折，显存峰值依旧由高精度激活缓存主导。换句话说，旧量化方案在视频 DiT 上“压得动权重、压不动激活”，而激活恰恰是带宽主项。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-4\">四 · 旧方案三：步数蒸馏与量化各自为战</h3>\n<p>第三类做法是步数蒸馏：用全精度多步教师采样轨迹监督一个少步学生，把 <span>T</span> 从数十步压到几步。这在图像扩散上已有实践，逻辑上直接削减 <span>cost<sub>e2e</sub></span> 中的 <span>T</span> 因子。但在视频 DiT 的推理栈里，蒸馏与量化是两条互不相交的流水线：蒸馏在浮点精度下做，量化在另一个环节单独校准，二者既不共享学生网络，也不共享监督信号。后果是叠加失效——少步学生本身已经牺牲了一部分轨迹精度，再套上低比特激活量化，两类误差在同一前向里叠加，生成质量出现双重退化，且无法归因。</p>\n<p>论文的核心判断正是针对这一点：蒸馏与量化彼此割裂是旧方案的根本问题。它主张把时间一致性约束的激活量化与步数蒸馏放进同一条推理链、同一个学生网络中联合优化，让量化尺度在蒸馏训练中随梯度更新，而不是离线校准后冻结。这个判断的工程含义是：低比特少步推理的可行性不能靠两个独立环节的“各自最优”拼出来，必须把量化误差的校正项与蒸馏的监督项写进同一个损失。</p>\n<div class=\"formula\">$$\\mathcal{L}=\\mathcal{L}_{\\mathrm{diff}}+\\lambda\\sum_{k}\\left\\|\\epsilon_\\theta^{(k)}(x_t)-\\epsilon_{\\mathrm{tea}}^{(k)}(x_t)\\right\\|_2^2$$</div>\n<p>上式里第一项是扩散去噪损失，第二项是教师中间步预测的蒸馏项，<span>λ</span> 为权重；材料未给出教师步数、学生步数与 <span>λ</span> 的具体取值。注意这个损失结构本身不解决量化误差，它只是把蒸馏目标写清楚；量化侧需要另一条时间一致性约束（可学习尺度加时间维平滑先验）来压制离群激活，二者在训练中耦合。旧方案缺的正是这个耦合点。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-5\">五 · 为什么非改不可：三重代价在同一请求上叠加</h3>\n<p>把三条旧方案放回开场的服务现场，痛点是叠加而非并列的。全精度多步采样贡献了 <span>T</span> 因子；常规量化压不动激活，带宽主项 <span>F·N·d·b</span> 仍在；蒸馏与量化割裂使得即便压了步数也换不来低比特收益。三者相乘的结果是：首块时延由“步数 × 单步激活读写”决定，整段完成时延再由分块数与 VAE 解码串起来，显存峰值由激活缓存与并发块数决定。任何单点优化都只能削掉一个因子，剩下的因子继续把 SLO 顶穿。</p>\n<table class=\"mini\"><thead><tr><th>旧方案</th><th>压制的因子</th><th>未触及的代价</th><th>典型失败模式</th></tr></thead><tbody><tr><td>全精度多步采样</td><td>无</td><td>步数 × 激活带宽、显存峰值</td><td>批大小被激活缓存锁死在 1</td></tr><tr><td>权重-only / W8A8 量化</td><td>权重字节</td><td>激活带宽主项、时间维离群值</td><td>W4A4 下精度显著下降，退回高精度激活</td></tr><tr><td>独立步数蒸馏</td><td>步数 T</td><td>低比特激活误差叠加、多样性损失</td><td>少步 + 低比特双重退化，无法归因</td></tr></tbody></table>\n<p>具体到一个工程判断：在 Blackwell 档位上，NVFP4/FP8 张量核心提升了算力密度，理论上让低比特算子更有吸引力；但如果激活量化在时空注意力输入处引入的误差沿时间维累积，那么算力密度的提升会被“不敢用低比特激活”抵消。这就是“非改不可”的实质——不是追求纸面算力，而是让低比特激活真正可部署，从而把带宽与显存两个瓶颈一起松开。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-6\">六 · 旧方案留下的接口缺口：分块流式与量化误差的边界</h3>\n<p>还有一层痛点常被忽略：旧方案在长视频上依赖分块流式解码，把 latent 按时间块切分、逐块去噪、块间保留重叠区供 VAE 解码拼接。这个机制本身是为控制峰值显存而生的——显存峰值取决于同时在处理的块数与激活缓存，块过大就回退到更小分块，属于典型的分块溢出失败模式。但旧量化方案没有为分块边界设计任何时间一致性约束：每个块独立校准尺度，块与块之间的重叠区就成了量化误差的接缝，长视频下误差在接缝处累积，材料明确指出缺少失败模式分析。</p>\n<p>Q-VDiT 的切入点因此不只是“把比特压低”，而是把量化尺度的更新轴扩展到时间步与块：量化算子对激活做尺度裁剪后反量化，尺度按时间步与块更新，用于压制视频分支的跨帧离群值（材料未给出比特位宽与分组大小）。这个设计直接回应了旧方案在分块边界上的缺口——尺度不再是全局常量，而是跟着时间块走，重叠区的接缝有了可学习的补偿余地。推理侧则把 VAE 解码与去噪阶段分离，解码按块流式进行以降低峰值显存，材料未给出解码吞吐与分辨率对应关系。</p>\n<p>需要诚实标注的是：这篇论文的材料未给出硬件档位、并行拓扑与 SLO 实测，也未给出 FVD、步数与显存的具体数字。因此本片段对旧方案痛点的刻画停留在机制层面——延迟主项是 <span>T·F·N·d·b</span>，显存峰值由块数与激活缓存决定，精度损失来自时间维离群值与量化/蒸馏割裂。这些是结构性的，不依赖具体测量即可成立；而收益能否兑现，取决于后续片段要展开的联合优化是否真的把这三个因子同时压住，以及分块边界的时间一致性误差是否被尺度更新机制吸收。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-7\">七 · 在线短视频生成的显存墙：全精度多步采样为何撑不住</h3>\n<p>设想一个面向内容平台的在线视频生成服务：用户提交文本与首帧，期望在数秒内拿到一段数秒长的视频。请求按并发到达，SLO 由首块可播放时延与整段完成时延共同约束。在这类场景里，推理栈的主流做法是全精度多步视频 DiT 采样：条件编码后初始化完整时空 latent，逐步执行含跨帧时间注意力的时空注意力与 MLP，采样结束后整段送入 VAE 解码。代价集中在两处：一是激活显存，时空注意力的激活规模随帧数与分辨率线性甚至更快增长，多步采样要求这些激活在每一步重复生成，峰值显存被整段 latent 与中间激活同时钉住；二是带宽，每一步都要把权重与激活在 HBM 与计算单元之间搬运一遍，步数越多，带宽占用越接近算力占用，端到端时延被采样步数直接乘出来。对在线服务而言，这意味着单卡可承载的并发批大小被压到很小，扩容只能靠堆卡，而堆卡又引入跨卡切分 latent 时间维的通信开销。</p>\n<p>旧方案的失效条件很明确：当分辨率与帧数上升、批大小被迫降到 1 仍接近显存上限时，整段式采样无法通过调批来摊薄成本；当采样步数按质量要求保持在较高档位时，时延随步数线性增长，SLO 无法靠调度弥补。工程上常见的缓解手段是降分辨率、截短帧数或降低步数，三者都以生成质量为代价。量化被视为另一条出路：把权重与激活压到低比特，理论上能同时降低显存占用与带宽需求，Blackwell 档位的 NVFP4／FP8 张量核心也确实提供了更高的算力密度。但视频分支的激活在跨帧时间维上存在明显离群值，直接做 W4A4 激活量化会让时空注意力的输入误差沿时间维逐步累积，精度显著下降；而常规量化方法只按张量或通道统计尺度，缺少对时空激活分布时间一致性的建模。量化与步数蒸馏在旧栈里又是彼此割裂的两条线：量化感知训练只关心单步前向的数值误差，蒸馏只关心步数压缩，二者叠加时误差来源无法归因。</p>\n<div class=\"formula\">$$\\hat{A}=\\mathrm{clip}\\left(\\frac{A}{s_t}\\right)\\cdot s_t,\\quad \\mathcal{L}=\\mathcal{L}_{\\mathrm{diff}}+\\lambda\\sum_{k}\\left\\|\\epsilon_\\theta^{(k)}(x_t)-\\epsilon_{\\mathrm{tea}}^{(k)}(x_t)\\right\\|_2^2$$</div>\n<p>上式给出该方案的两个抓手：量化尺度 <em>s<sub>t</sub></em> 按时间步与块更新，用于压制跨帧离群值；蒸馏项以教师多步采样的中间噪声预测为监督，把少步学生拉回教师的轨迹。系统代价随之转移：显存峰值不再由整段 latent 决定，而由同时在处理的块数与激活缓存决定，块过大时触发显存溢出并回退到更小分块——这是典型的分块溢出失败模式，回退次数直接反映容量标定是否合理；VAE 解码与去噪阶段分离、按块流式拼接，重叠区用于抑制接缝，但重叠区的量化误差累积在长视频下缺少误差上界，属于需要在容量规划中单独监控的风险项。材料未给出比特位宽、分组大小、教师与学生步数、重叠比例及硬件档位下的实测吞吐，因此这套机制能否在给定 SLO 下兑现显存与带宽收益，只能停留在机制层面，落地时必须按分块大小与量化方案逐档标定。</p>\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-8\">八 · 请求形态的构成：长度由帧数与分块数共同决定</h3>\n<p>在 Q-VDiT 的推理链里，“输入长度”不是文本 token 数，而是 latent 序列沿时间维被切成的去噪单元数。条件编码（文本或首帧）完成后得到固定分辨率视频 latent，按时间块切分为去噪单元，因此一次请求的计算量近似正比于块数乘以每块内时空注意力的激活规模。测量口径必须把三件事分开记录：总帧数 <em>F</em>、分块大小 <em>B</em>（每块帧数）、重叠帧数 <em>O</em>。有效块数可写成</p>\n<div class=\"formula\">$$N_{\\text{blk}}=\\left\\lceil \\frac{F-O}{B-O}\\right\\rceil$$</div>\n<p>这个式子决定了负载的“长度分布”实际是离散的：<em>F</em> 连续变化时 <em>N</em><sub>blk</sub> 呈阶梯跳变，阶梯边界就是容量规划的分档点。工程上应把请求按 (<em>F</em>, 分辨率, <em>B</em>) 三元组打桶统计，而不是只报平均帧数——平均帧数会把阶梯效应抹平，导致按均值配卡时在跳变档位上出现显存溢出回退。一个具体例子：同一段 121 帧的请求，在 <em>B</em>=16、<em>O</em>=4 时块数为 10 量级，若把 <em>B</em> 降到 8，块数翻倍而每块激活减半，端到端时延未必改善，因为块间重叠与 VAE 拼接开销随块数线性增长。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-9\">九 · 并发与批大小：激活显存是硬约束，不是算力</h3>\n<p>视频 DiT 的批维度与块维度在显存上近似可加：峰值显存由同时在处理的块数与激活缓存决定。设单块激活峰值为 <em>M</em><sub>act</sub>(<em>B</em>, <em>H</em>, <em>W</em>)，并发块数为 <em>C</em>，则粗算约束为</p>\n<div class=\"formula\">$$C\\cdot M_{\\text{act}}(B,H,W)+M_{\\text{w}}+M_{\\text{vae}} \\le M_{\\text{cap}}$$</div>\n<p>其中 <em>M</em><sub>w</sub> 是分组量化后的权重驻留，<em>M</em><sub>vae</sub> 是分离出的 VAE 解码阶段占用。注意低比特量化并不缩小激活缓存的全部——伪量化算子在注意力输入与 MLP 激活处插入，中间结果仍需以低比特形式驻留，但反量化与累加的工作区仍按较高精度分配，因此 W4A4 的显存收益小于按位宽线性外推的直觉值。这直接塑造批调度：Q-VDiT 的天然批单位是“块”而非“请求”，并发请求按块交错调度，批大小受 <em>C</em> 约束而非受 SM 占用率约束。代价体现在吞吐上——块级调度让张量核心的 MMA 形状偏小（每块内序列长度有限），算力密度利用率低于把多请求拼成大批的 LLM 式连续批处理；这是视频生成与文本推理在批形态上的根本差异。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-10\">十 · SLO 的两个时间尺度：首块时延与整段完成时延</h3>\n<p>流式输出把 SLO 拆成两段。首块输出时延 <em>T</em><sub>first</sub> 覆盖条件编码、首块去噪与首块 VAE 解码；整段完成时延 <em>T</em><sub>total</sub> 覆盖全部 <em>N</em><sub>blk</sub> 块去噪加逐块解码拼接。可写成</p>\n<div class=\"formula\">$$T_{\\text{total}}\\approx T_{\\text{enc}}+N_{\\text{blk}}\\cdot\\left(T_{\\text{den}}+T_{\\text{vae}}^{\\text{blk}}\\right)+T_{\\text{stitch}}$$</div>\n<p>其中 <em>T</em><sub>den</sub> 是单块在少步蒸馏调度下的去噪时延（步数已由蒸馏压缩，但每步仍含时空注意力与 MLP 的低比特算子），<em>T</em><sub>stitch</sub> 是重叠区拼接开销。这里的关键工程判断是：<em>T</em><sub>first</sub> 由单块决定，与 <em>N</em><sub>blk</sub> 无关，因此长视频请求的 SLO 违约通常发生在 <em>T</em><sub>total</sub> 而非首块；而短请求（块数少）的违约更可能来自固定开销 <em>T</em><sub>enc</sub> 与首块冷启动。容量规划应分别对这两个指标设阈值并分别统计分位数，只报端到端平均时延会掩盖长尾——长尾恰恰来自块数阶梯跳变与显存溢出回退的叠加。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-11\">十一 · 长尾的三个来源与可核查的测量口径</h3>\n<p>长尾不是统计噪声，是机制产物。来源一：块数阶梯。请求帧数落在阶梯边界附近时，块数比邻近请求多一档，时延跳变一个 <em>T</em><sub>den</sub>+<em>T</em><sub>vae</sub><sup>blk</sup>。来源二：显存溢出回退。块过大触发回退到更小分块，块数增加且重叠比例上升，单请求时延非线性放大，这是典型的分块溢出失败模式；监控必须记录回退次数与回退前后块大小，否则长尾无法归因。来源三：量化误差沿时间维累积。低比特激活在时空注意力输入处引入误差，长视频下误差沿时间维累积，材料未给出误差上界或补偿机制，因此长请求的质量风险随时长单调上升，需在质量 SLO 上单独设时长上限而非只设时延上限。</p>\n<p>可核查口径建议如下表，每项都要求按请求打点而非按集群聚合：</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>定义</th><th>用途</th></tr></thead><tbody>\n<tr><td>块数分布</td><td>按 (<em>F</em>,<em>B</em>,<em>O</em>) 打桶的 <em>N</em><sub>blk</sub> 直方图</td><td>识别阶梯边界，定分档</td></tr>\n<tr><td>每块去噪时延</td><td>单块从量化算子输入到 latent 输出的墙钟</td><td>分离 <em>T</em><sub>den</sub> 与调度开销</td></tr>\n<tr><td>VAE 解码时延</td><td>按块计的解码墙钟</td><td>验证去噪/解码分离的收益</td></tr>\n<tr><td>溢出回退次数</td><td>触发更小分块的请求占比</td><td>长尾归因，容量红线</td></tr>\n<tr><td>峰值显存</td><td>每请求 <em>C</em>·<em>M</em><sub>act</sub>+<em>M</em><sub>w</sub>+<em>M</em><sub>vae</sub> 的实测峰值</td><td>校准 <em>C</em> 上限</td></tr>\n<tr><td>首块/整段时延分位</td><td><em>T</em><sub>first</sub> 与 <em>T</em><sub>total</sub> 的 p50/p99</td><td>SLO 双阈值判定</td></tr>\n</tbody></table>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-12\">十二 · 方案反过来限制负载：分块上限即准入控制</h3>\n<p>负载塑造方案，方案也反向裁剪负载。Q-VDiT 的分块流式结构给系统加了三道隐式限制。第一，分辨率与帧数变化会改变时空注意力激活规模，需按档位设定分块上限；超过上限的请求要么被拒、要么被降档（降分辨率或降帧数），这实质是准入控制，必须在网关层显式实现而不是让回退机制在运行时兜底。第二，少步蒸馏压缩了步数，但也压缩了调度弹性：步数少意味着单块内可插入的流水重叠点少，块间流水（去噪与 VAE 解码重叠）的收益受 <em>T</em><sub>den</sub> 与 <em>T</em><sub>vae</sub><sup>blk</sup> 比例约束，若解码占比高则流水收益有限，此时增大 <em>C</em> 比加深流水更有效。第三，低比特量化与少步蒸馏叠加可能同时损失细节与运动多样性，材料未给出多样性指标，因此质量侧的负载限制应保守：对长视频与高运动场景设更严的时长/分辨率上限，把风险挡在准入层而非留给事后评估。</p>\n<p>一个具体机制层面的例子：若某档位下 <em>M</em><sub>cap</sub> 只允许 <em>C</em>=2 个块并发，则两个并发请求各占一块时，第三个请求只能排队等块释放，队头阻塞发生在块粒度而非请求粒度——这比请求级批调度更细，但也意味着单请求的长视频会长期占用一个并发槽，短请求被长请求挤占。缓解手段是按块数给请求加权配额，而非按请求数均分。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-13\">十三 · 容量标定的落地顺序</h3>\n<p>材料未给出硬件档位、并行拓扑与 SLO 实测，容量判断只能停留在机制层面，因此标定顺序必须是先测后配。第一步固定 (<em>B</em>,<em>O</em>) 与分辨率，扫 <em>C</em> 直到峰值显存逼近 <em>M</em><sub>cap</sub>，记录回退次数随 <em>C</em> 的变化曲线，回退次数由零转正的拐点就是该档位的并发上限。第二步在该上限下测 <em>T</em><sub>den</sub> 与 <em>T</em><sub>vae</sub><sup>blk</sup> 的比例，决定块间流水是否值得做。第三步按块数分布直方图定分档边界，把阶梯跳变对齐到业务可接受的时延档。第四步才是量化方案与蒸馏步数的选择——因为量化收益（显存带宽与采样时延）与分块大小强耦合，脱离分块谈 W4A4 的收益没有意义。跨卡切分需按 latent 时间维评估通信代价，在 NVLink 5 域内切时间维的通信量与块边界重叠区大小相关，材料未给出并行拓扑，这一步只能作为待测项列出而非默认开启。</p>\n<p>最终落在一条工程判断上：Q-VDiT 的负载形态由 <em>N</em><sub>blk</sub> 的阶梯与 <em>C</em> 的显存上限共同定义，SLO 必须双尺度测量，长尾必须按回退次数归因而非按均值平滑；在缺少硬件档位实测的前提下，任何吞吐承诺都应表述为“在给定 (<em>B</em>,<em>O</em>,<em>C</em>) 标定后成立”，而不是无条件成立。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-14\">十四 · 分块流式解码把负载从“请求级”改写成“块级”</h3>\n<p>Q-VDiT 的推理负载不是一条请求一个批，而是被切成时间块后的块队列。请求长度由帧数与分块数决定，分辨率与帧数变化直接改变时空注意力激活规模，因此“输入长度分布”在视频场景里应读作“块数分布 × 每块激活字节数”，而不是文本 token 数。批大小受激活显存约束：长视频倾向小批分块流式处理，短请求才可能并批。并发请求下按块调度，SLO 必须拆成两个口径——首块输出时延（用户看到第一段画面）与整段完成时延（全片可播），二者对块大小的敏感方向相反：块越大，首块越晚但块间重叠开销占比越低；块越小，首块越快但重叠区重复计算与量化误差在边界处累积的次数越多。可核查的测量口径是每块去噪时延、VAE 解码时延、块溢出回退次数、同时在处理的块数与激活缓存峰值，四者必须同窗口采样，否则吞吐数字无法归因。</p>\n<p>负载塑造方案的方式体现在量化尺度的更新粒度上：尺度按时间步与块更新，用于压制视频分支的跨帧离群值，因此块边界就是尺度边界。若把块切得过细，每块独立校准的尺度在块间不连续，重叠区拼接时会出现可见的亮度/纹理跳变；若块过大，激活缓存峰值上升，一旦超过预算就触发回退到更小分块，而回退本身改变块边界，等于在运行中重排了尺度更新点，这是该方案最典型的失效条件。显存峰值可写成 <span class=\"formula\">$$M_{\\text{peak}} \\approx B_{\\text{blk}}\\cdot (A_{\\text{attn}}+A_{\\text{mlp}}) + M_{\\text{VAE}}^{\\text{chunk}}$$</span> 其中同时在处理的块数 <em>B</em><sub>blk</sub> 与每块激活缓存是主项，VAE 解码与去噪阶段分离后，解码按块流式进行，峰值只取决于当前解码块而非全片 latent。代价是解码吞吐与分辨率强相关，材料未给出对应关系，容量标定只能按块逐一测。</p>\n<p>反过来，方案也限制负载：低比特激活在时空注意力输入处引入量化误差，长视频下误差沿时间维累积，材料未给出误差上界或补偿机制，因此可服务的帧数上限不是由显存单独决定，而是由“块数 × 每块误差”的可接受累积决定。蒸馏把学生步数压到少于教师，步数调度成为负载的一部分——少步意味着单块去噪时延下降，但块间重叠区仍需按重叠比例重复前向，重叠比例材料未给出，工程上必须把它当作可调参数纳入 SLO 预算。该方案未给出批调度、投机解码或分离式预填/解码的机制设计，因此并发上升时只能靠块级队列削峰，不能靠请求级连续批处理提升张量核心利用率；这是与通用 LLM  serving 栈的结构性差异，也是容量规划时必须单独建模的部分。</p>\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>对方案的约束</th><th>可核查口径</th></tr></thead><tbody><tr><td>帧数/块数</td><td>块数越多，尺度边界越多，时间维误差累积越长</td><td>块数分布、每块去噪时延</td></tr><tr><td>分辨率</td><td>激活规模上升，触发块溢出回退</td><td>回退次数、激活缓存峰值</td></tr><tr><td>并发</td><td>块级队列削峰，无请求级并批</td><td>首块时延、整段完成时延</td></tr><tr><td>步数调度</td><td>少步降低单块时延，重叠区重复前向仍在</td><td>每块前向次数、VAE 解码时延</td></tr></tbody></table>\n<p>工程判断落在块大小这一旋钮上：它同时是显存预算、尺度更新粒度、重叠开销与首块 SLO 的交点。材料未给出硬件档位、并行拓扑与 SLO 实测，因此不能据此推断实际吞吐或显存收益；落地时须按分块大小与量化方案做容量标定，并把“块溢出回退次数”作为一级告警——回退频繁说明块上限设错，量化尺度在运行中被反复重排，精度与尾延迟会同时恶化。</p>\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-15\">十五 · 伪量化算子的数值解剖：clip、尺度与反量化</h3>\n<p>Q-VDiT 的量化侧在注意力输入与 MLP 激活上插入低比特伪量化算子，其数值形式是 <span class=\"formula\">$$\\hat{A}=\\mathrm{clip}\\left(\\frac{A}{s_t}\\right)\\cdot s_t$$</span> 这个式子必须逐项拆开看，因为每一项都对应一个推理代价。A 是该时间块内某一层激活张量，形状由批内 token 数与隐藏维决定；除以 s_t 是归一化到量化栅格，clip 把超出栅格范围的值截断到可表示区间，再乘回 s_t 完成反量化。关键在 s_t 的下标：尺度按时间步与块更新，而不是全局一个标量。视频分支的激活离群值具有跨帧漂移特性——某一帧的注意力 logits 尖峰在下一帧可能不复现，全局尺度要么被尖峰拉大而牺牲其余帧的分辨率，要么被均值压低而截断尖峰。按块更新的尺度把误差局部化，代价是每个块都要携带一组尺度元数据，在分块流式解码时随激活缓存一起驻留显存。</p>\n<p>clip 的截断不是免费的。被截断的激活在反量化后与真值产生偏差，这个偏差进入时空注意力的 softmax 前 logits，经指数放大后改变注意力权重分布。工程上要区分两种误差：栅格化误差（除以 s_t 后的舍入）与截断误差（clip 丢掉的部分）。前者随比特位宽下降而线性增长，后者是重尾分布的函数——视频激活的离群值越重，截断误差越难用尺度调节压住。材料未给出比特位宽与分组大小，因此无法给出误差上界；但从机制上，s_t 的可学习性正是把这两类误差在训练中显式暴露给蒸馏损失的手段。</p>\n<p>权重量化走分组路线，与激活的单块尺度不同：权重按通道组共享尺度，推理时权重在加载阶段即完成反量化或保持低比特参与 MMA。这决定了 kernel 的数据流——激活是运行时动态量化的，权重是静态的，两者在张量核心上的排布方式不同，前者需要在 SM 内做 scale 乘法，后者可在加载时折叠。对 Blackwell 的 tcgen05 路径而言，激活的动态尺度意味着不能把量化完全折叠进权重预处理，必须在 MMA 之前插入逐块的缩放步骤，这一步的吞吐取决于尺度广播的寄存器压力。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-16\">十六 · 累加精度：低比特乘、高精度加的边界</h3>\n<p>低比特算子真正的数值风险不在乘法而在累加。FP8 或 NVFP4 的乘积累加若在低精度累加器里完成，时空注意力这种长归约（归约长度等于时空 token 数）会迅速吃掉有效位。第五代 Tensor Core 的 MMA 指令在架构上支持高精度累加，工程判断是：乘数位宽可以降到 4 或 8 比特，累加必须留在 FP32 或至少 BF16 级别的累加器里，否则误差随归约长度线性叠加，且不可通过事后校正挽回。</p>\n<div class=\"formula\">$$\\mathrm{err}_{\\mathrm{acc}}\\approx\\sqrt{N}\\cdot\\epsilon_{\\mathrm{mul}}\\cdot\\|A\\|\\|W\\|,\\quad N=\\text{归约长度}$$</div>\n<p>这里 N 是单次 MMA 的归约深度，ε_mul 是乘数栅格化的相对误差。视频 DiT 的时空注意力把帧内空间 token 与跨帧时间 token 拼进同一归约，N 随分辨率与帧数增长，误差随 √N 上升。这解释了为什么长视频下低比特激活的精度衰减比图像 DiT 更严重：不是乘数更差，是归约更长。分块去噪把这个 N 切成块内归约加块间重叠，块内 N 变小、误差被局部化，但块边界处的信息交换仍需高精度，否则重叠区的拼接会出现数值接缝。</p>\n<p>代价面：高精度累加器占用寄存器与 TMEM 带宽。FP32 累加在 tcgen05 的 TMEM 中占据的列数与低精度操作数不同，累加器位宽直接决定单 SM 能并发的 MMA 数量。若为了压显存把累加也降到 BF16，吞吐上升但长归约误差不可控；若坚持 FP32 累加，TMEM 容量成为并发的硬约束，进而影响分块大小——块越大，单块内归约越长，越需要 FP32 累加，TMEM 压力越大。这是一个显存—精度—吞吐的三角权衡，材料未给出具体档位，只能按机制定性。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-17\">十七 · Blackwell 数据通路：tcgen05、TMEM 与 2-SM MMA</h3>\n<p>在 SM100/SM103 上，低比特矩阵乘走 tcgen05 系列指令，操作数从共享内存或张量内存喂入，累加结果落在 TMEM。TMEM 是张量核心私有的暂存区，与寄存器文件和共享内存分离，其容量决定了单个 MMA 流水能驻留多少累加器分片。对 Q-VDiT 这类逐块量化的负载，TMEM 的意义在于：激活的尺度乘法与反量化可以在 MMA 前的数据准备阶段完成，累加器常驻 TMEM 不被逐元素操作打断，从而把量化开销藏在 MMA 流水后面。</p>\n<p>2-SM MMA 是另一条通路：两个 SM 协同完成一次更大的 MMA，操作数跨 SM 对分，累加器也跨 SM 分布。它把单次 MMA 的归约深度与输出宽度推高，适合时空注意力里大而规整的矩阵乘；代价是跨 SM 的数据交换与同步，若分块后的矩阵形状不规整（块边界 token 数不是 MMA 友好的倍数），2-SM 的收益会被填充与同步吃掉。工程判断是：分块大小应与 MMA 的 tile 形状对齐，让块内归约落在 2-SM 的整 tile 上，块间重叠区单独走小 tile 路径，避免用 2-SM 处理边角料。</p>\n<table class=\"mini\"><thead><tr><th>通路</th><th>数值角色</th><th>推理代价</th></tr></thead><tbody><tr><td>tcgen05 + TMEM</td><td>低比特乘、高精度累加常驻</td><td>TMEM 容量限制并发 MMA 数与块大小</td></tr><tr><td>2-SM MMA</td><td>大 tile 时空注意力归约</td><td>跨 SM 同步与填充开销，形状不规整时收益衰减</td></tr><tr><td>分组权重量化</td><td>加载时反量化或保持低比特</td><td>权重带宽下降，但尺度元数据占额外显存</td></tr></tbody></table>\n<p>具体例子：一个时间块的时空注意力，块内 token 数为空间 token 乘块内帧数。若该数能被 2-SM tile 整除，MMA 流水满负荷，累加器在 TMEM 中按 FP32 驻留；若块被切得过小以压显存，tile 填充率下降，2-SM 的跨 SM 同步变成纯开销，此时退回单 SM MMA 反而更稳。这正是分块溢出回退机制在数值层面的另一面：回退不只是显存策略，也是 MMA 形状策略。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-18\">十八 · 数据类型谱系：FP16/BF16 到 FP8 到 NVFP4 的取舍</h3>\n<p>精度档位的选择不是单调的“越低越快”。BF16 与 FP16 在 Blackwell 上走同一类张量核心路径，动态范围与尾数取舍不同：BF16 宽指数窄尾数，适合激活离群值大的场景；FP16 窄指数宽尾数，适合权重量化后分布集中的场景。视频 DiT 的激活离群值特性使 BF16 在中间激活上更稳，而权重分组量化后分布被压缩，FP16 的尾数优势可用。这是混合精度的常见起点，材料未给出具体档位，但机制上可推断：激活侧偏 BF16 保范围，权重侧可更激进。</p>\n<p>FP8 分 E4M3 与 E5M2 两族，前者尾数多、范围窄，后者范围宽、尾数少。对逐块量化的激活，E4M3 在块内分布集中时分辨率更好，E5M2 在跨帧离群值漂移时不易饱和。NVFP4 把位宽再压一档，块级尺度成为必需——没有块级尺度，4 比特栅格无法覆盖视频激活的动态范围。代价是尺度元数据的显存与带宽占比上升：位宽越低，每元素的有效载荷越小，尺度与索引的开销占比越大，分组越细开销越高。这是低比特量化的固定税，材料未给出分组大小，因此无法量化这笔税的比例，但方向确定：分组越细，精度越好，元数据带宽越重。</p>\n<ul><li>激活侧：块级尺度 + 时间维平滑先验，抑制跨帧离群值，代价是尺度随块驻留显存。</li><li>权重侧：分组量化，加载时反量化或低比特直入 MMA，代价是尺度元数据占带宽。</li><li>累加侧：FP32 累加器常驻 TMEM，代价是 TMEM 容量约束并发与块大小。</li><li>块边界：重叠区需高精度交换，代价是重叠比例直接吃显存与算力。</li></ul>\n<p>具体代价链：位宽从 BF16 降到 NVFP4，激活显存带宽名义上降为四分之一，但尺度元数据与重叠区使有效降幅打折；同时 MMA 吞吐上升，若累加仍为 FP32，TMEM 成为新瓶颈，端到端时延的改善取决于哪一环先饱和。这就是为什么低比特收益必须与分块大小联合标定，而不能只看位宽数字。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-19\">十九 · 量化误差与蒸馏损失的耦合：公式逐项</h3>\n<p>训练侧的联合损失是 <span class=\"formula\">$$\\mathcal{L}=\\mathcal{L}_{\\mathrm{diff}}+\\lambda\\sum_{k}\\left\\|\\epsilon_\\theta^{(k)}(x_t)-\\epsilon_{\\mathrm{tea}}^{(k)}(x_t)\\right\\|_2^2$$</span> 第一项是扩散去噪损失，作用于学生网络在低比特伪量化下的噪声预测；第二项是蒸馏项，k 遍历教师多步采样的中间步，把教师在同一 x_t 上的噪声预测作为监督。逐项看：ε_θ^(k) 是学生在第 k 个蒸馏监督点上的输出，已经过量化算子，因此这一项的梯度会回传到量化尺度 s_t——这是量化与蒸馏不割裂的机制所在。λ 加权两项，材料未给出取值，但从机制上 λ 过大时学生被拉向教师轨迹而牺牲自身去噪能力，λ 过小时量化误差得不到蒸馏信号的纠正。</p>\n<p>时间一致性约束体现在 s_t 的更新上：尺度按时间步与块学习，平滑先验使相邻块的尺度不剧烈跳变，从而让跨帧激活的量化栅格连续。若尺度逐块独立学习而无平滑，块边界处栅格突变，重叠区拼接出现数值接缝，这正是长视频分块边界误差累积的一个来源。代价面：蒸馏项需要对教师中间潜变量做前向，这部分仅离线用于监督，不进入推理链，因此不占推理时延；但训练侧的显存与算力开销落在教师多步采样上，与推理侧的显存预算无关。</p>\n<p>推理时这条链的落点是：学生按少步调度推进，每步内激活经 s_t 量化后进 MMA，累加在 TMEM 中保持高精度，块间重叠区用高精度路径交换。端到端时延由少步调度与每块去噪时延共同决定，显存峰值由同时在处理的块数与激活缓存决定。量化误差若在块边界累积，表现为重叠区拼接的质量下降而非时延变化——这是精度问题伪装成显存问题的典型失败模式，监控上需要把块边界误差与显存溢出回退分开计数。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-20\">二十 · 工程判断：精度档位与分块形状的联合标定</h3>\n<p>把上述机制收拢成可执行的标定顺序：先定累加精度（FP32 累加是长归约的底线），再定激活位宽与分组（块级尺度是 NVFP4 的必要条件），再定分块大小与重叠比例（与 MMA tile 形状对齐，避免 2-SM 处理边角料），最后用蒸馏后的少步调度压时延。每一步都改变显存峰值与吞吐的瓶颈位置，因此不能单独调一个参数。材料未给出硬件档位与 SLO 实测，容量判断只能停在机制层面：若 TMEM 先饱和，降位宽无用；若激活带宽先饱和，降位宽有效但尺度元数据打折；若块边界误差先暴露，需提高重叠区精度而非继续压位宽。</p>\n<p>一个具体的工程判断落在回退逻辑上：块过大触发显存溢出时回退到更小分块，但小分块使 MMA tile 填充率下降、块间重叠比例上升、尺度元数据开销占比上升，三者叠加可能使回退后的端到端时延不降反升。因此回退阈值应按“显存峰值 + MMA 填充率 + 重叠开销”联合设定，而不是单看显存水位。这也是 Q-VDiT 这类逐块量化方案在 Blackwell 上落地时最容易被忽略的一环：数值精度的选择与分块形状的选择是同一个决策，拆开调就会在某一环上撞墙。</p>\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-21\">二十一 · 显存账本的三层结构与可复算预算</h3>\n<p>在视频 DiT 推理中，显存不是一块整账，而是三层叠加：权重、激活、KV/中间潜变量缓存。Q-VDiT 的量化侧把权重压到分组低比特、把注意力输入与 MLP 激活压到 W4A4 级别的伪量化算子，直接改变前两层的字节数；第三层则由分块流式解码的块数与重叠区决定。给出一个可复算的预算框架，比记住某个具体数字更有用。</p>\n<p>设主干参数量为 P、权重平均位宽为 b_w、激活每元素位宽为 b_a、单块 latent 的 token 数为 N_blk、隐藏维为 d、层数为 L、同时在处理的块数为 C、每块保留的中间激活缓冲份数为 k_buf。则稳态显存近似为：</p>\n<div class=\"formula\">$$M \\approx \\underbrace{\\frac{P \\cdot b_w}{8}}_{\\text{权重}} + \\underbrace{C \\cdot k_{\\text{buf}} \\cdot N_{\\text{blk}} \\cdot d \\cdot L \\cdot \\frac{b_a}{8}}_{\\text{激活}} + \\underbrace{C \\cdot N_{\\text{blk}} \\cdot d \\cdot \\frac{b_{\\text{kv}}}{8}}_{\\text{KV/潜变量}} + M_{\\text{VAE}} + M_{\\text{runtime}}$$</div>\n<p>三项的量级关系决定优化方向。权重项与批大小无关，是固定成本；激活项随 C、N_blk、L 线性增长，是视频 DiT 的主要压力源；KV/潜变量项在分块流式中被压缩到只保留当前块与重叠区。举例：若 d=3072、L=32、N_blk 取一个时间块内的时空 token 数、C=1、k_buf=2，激活项在 b_a=16 与 b_a=4 之间的差距就是四倍——这正是 Q-VDiT 把激活量化当作显存杠杆而非单纯算力杠杆的原因。工程上先算激活项，再倒推 C 的上限，最后核对权重项与 VAE 解码器是否放得下。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-22\">二十二 · 分页与分块：把峰值显存从“全序列”压到“块+重叠”</h3>\n<p>视频 DiT 的时空注意力天然要求整段 latent 可见，但 Q-VDiT 的推理组织是逐时间块去噪、块间保留重叠区供 VAE 拼接。这等价于把注意力的可见范围从全序列收缩到块内加有限重叠，显存峰值不再随总帧数线性增长，而随块大小与并发块数增长。分页在这里的作用不是操作系统式的换页，而是把 KV/潜变量按块分配、按块释放：一个块去噪完成后其激活缓存立即归还，只有重叠区被保留给下一块与解码拼接。</p>\n<p>代价转移很明确：块越小，峰值显存越低，但重叠区占比上升、块边界处的时间一致性误差累积风险变大，且每块的固定开销（kernel 启动、量化尺度更新、VAE 解码调用）被摊薄得更差，端到端时延上升。块越大，单块时空注意力在 Blackwell 张量核心上的利用率越好，但激活项按 N_blk 线性膨胀，一旦超过预算就触发材料中描述的“块过大回退到更小分块”的溢出失败模式。这个回退不是无损的：回退发生时正在处理的块需要重新切分，已经算出的部分激活被丢弃，等效于一次重算，直接体现为首块输出时延的抖动。</p>\n<p>可操作的判据是：令块大小满足激活项不超过总预算的某个固定比例，再令重叠比例满足 VAE 拼接的接缝抑制需求，两者取交集。由于材料未给出重叠比例与比特位宽，落地时必须用一次标定运行把这两个参数钉死，而不是沿用默认值。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-23\">二十三 · 压缩与复用：量化尺度的时间维语义</h3>\n<p>Q-VDiT 的量化算子形式为 <span>$$\\hat{A}=\\mathrm{clip}(A/s_t)\\cdot s_t$$</span>，尺度 s_t 按时间步与块更新。这个设计的显存含义常被忽略：尺度本身是一份需要常驻的元数据，若按每个时间步、每个块、每个通道组各存一份，其字节数在长视频、多块并发时会变成不可忽视的第四项开销。分组量化把尺度数量压到“组数×时间步×块数”，组越大尺度越省但离群值抑制越弱，这是精度与显存的直接交换。</p>\n<p>复用发生在两个层面。其一是块间复用：重叠区的激活在相邻两块中被重复计算，若把重叠区的量化后激活缓存下来直接喂给下一块，可省一次前向的一部分，但缓存本身占用显存，且量化误差在复用中被固化而非重新校正——材料指出长视频下误差沿时间维累积、缺少误差上界或补偿机制，复用会放大这一风险。其二是解码阶段复用：VAE 解码与去噪分离，解码按块流式进行，去噪阶段的激活在进入解码前即可释放，峰值显存因此由“去噪块”与“解码块”中较大者决定，而非两者之和。工程判断是：优先做阶段分离带来的释放，谨慎做跨块激活复用，后者只在重叠比例小、块数少时划算。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-24\">二十四 · 卸载：VAE 与条件编码器的位置</h3>\n<p>卸载的对象不是主干，而是那些“低频但占地方”的组件。VAE 解码器在分块流式下每块调用一次，其权重与中间特征图在解码瞬间构成一个独立峰值；条件编码器（文本/首帧）在请求开始时用一次，之后长期闲置。把这两者放在与去噪主干不同的显存池、按需加载按需释放，可以让去噪阶段的激活预算不被它们挤占。</p>\n<p>卸载的代价是 PCIe 或主机内存往返带宽。以每块解码一次计，若解码器权重每次都要重新搬入，搬运时间会直接叠加到每块解码时延上，在首块输出时延敏感的 SLO 下不可接受。更合理的做法是：解码器权重常驻但特征图缓冲按块复用，条件编码器在批内多请求共享时保留、单请求结束后释放。这与材料中“VAE 解码与去噪阶段分离以控制峰值显存”的表述一致，但材料未给出解码吞吐与分辨率的对应关系，因此卸载策略的收益必须按实际分辨率标定，不能假设解码总是便宜的一方。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-25\">二十五 · 带宽瓶颈的位置与 HBM3e 容量口径</h3>\n<p>低比特量化把算力密度提上去之后，瓶颈往往从算力转到带宽。视频 DiT 的带宽压力有三个来源：权重流（每步前向都要读一遍全部权重）、激活读写（时空注意力的 QKV 与输出在片上与 HBM 之间往返）、以及 KV/潜变量的分块搬运。权重流在批大小大于 1 时被摊薄，因此小批、长视频、多块的形态下激活读写占比更高；这正是 Q-VDiT 用 W4A4 同时压权重与激活的动机——它压的是两个带宽来源，而不只是算力。</p>\n<p>HBM3e 容量的算法口径是：单卡容量除以（权重字节 + 每并发块激活字节 + 运行时与框架开销），得到可并发的块数上限，再乘以每块 token 数得到有效批容量。注意这里的除法不是连续的：块数是整数，且受重叠区与解码缓冲的额外占用影响，实际可用块数通常比理论值少一档。容量规划时应把理论值向下取整后再留一份余量给量化尺度元数据与回退重算的临时缓冲。材料未给出硬件档位与并行拓扑，跨卡切分 latent 时间维时的通信代价无法在此定量，只能定性判断：切分越细，块边界越多，重叠区与通信次数同步上升。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-26\">二十六 · 失败模式与标定清单</h3>\n<p>显存账本最容易出错的地方不是公式，而是把稳态值当成峰值。分块流式的真实峰值出现在“上一块激活尚未释放、下一块重叠区已分配、解码缓冲同时在场”的交叠瞬间，这个瞬间的占用比稳态公式高出重叠区与解码缓冲两项。Q-VDiT 的溢出回退机制正是为这个瞬间设计的兜底，但回退本身带来重算与时延抖动，属于典型的失败模式而非正常路径。</p>\n<ul>\n<li>标定项一：按目标分辨率与帧数测出单块激活字节，反解 C 的上限，而不是先定 C 再试分辨率。</li>\n<li>标定项二：测重叠比例对 VAE 接缝与时间一致性的影响，同时记录重叠区量化误差是否随块序号单调增长。</li>\n<li>标定项三：分别评估低比特量化与少步蒸馏对细节与运动多样性的影响，材料明确指出两者叠加可能同时损失二者，需分开归因。</li>\n<li>标定项四：记录每块去噪时延、VAE 解码时延与回退次数，把回退次数当作容量是否过紧的一阶指标。</li>\n</ul>\n<p>工程判断落在分块大小与量化方案的联合标定上：在 Blackwell 档位上，先以激活项定块上限，再以重叠比例定块下限，两者夹出的区间若为空，说明该分辨率下必须降并发或改量化分组，而不是继续调调度参数。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-27\">二十七 · 分块流式解码下的显存账本与带宽瓶颈</h3>\n<p>Q-VDiT 的显存峰值不在权重，而在“同时在处理的块数 × 每块激活缓存”。按材料给出的推理流程，一次请求先编码条件并初始化 latent，再按时间块切分逐块去噪；每块内激活经时间一致性量化算子压到低比特后送入张量核心，块间保留重叠区供 VAE 解码拼接。设块数为 <span class=\"inline-math\">N_b</span>、每块时空 latent 元素数为 <span class=\"inline-math\">E_b</span>、每元素激活字节为 <span class=\"inline-math\">a</span>（低比特量化后显著小于 FP16）、重叠比例为 <span class=\"inline-math\">r</span>，则激活账本可写成 <div class=\"formula\">$$M_{\\text{act}} \\approx N_b\\,(1+r)\\,E_b\\,a \\;+\\; M_{\\text{quant-scale}} \\;+\\; M_{\\text{attn-ws}}$$</div> 其中 <span class=\"inline-math\">\\(M_{\\text{quant-scale}}\\)</span> 是随训练更新、按时间步与块刷新的可学习尺度表，<span class=\"inline-math\">\\(M_{\\text{attn-ws}}\\)</span> 是时空注意力与跨帧时间注意力的工作区。权重侧因采用分组量化而按组存放尺度，容量随组数线性增长；KV／激活缓存按块释放，这是该方案把峰值压下来的关键机制——去噪完一块即释放其激活，只保留重叠区供拼接。</p>\n<p>带宽瓶颈的位置由阶段决定。去噪阶段是计算与激活读写混合：低比特激活降低了每次时空注意力的读带宽，但量化—反量化的裁剪与尺度更新引入额外访存，且时间一致性尺度需按时间步刷新，形成周期性小写入。VAE 解码阶段与去噪分离、按块流式进行，此时瓶颈转为解码器的权重流式读取与像素写回，峰值显存取决于解码块大小而非整段视频。工程判断是：若把解码与去噪混在同一驻留窗口，峰值会被解码器权重与去噪激活叠加顶高，因此材料明确将两阶段分离。代价上，分离带来块间同步与重叠区重复计算，重叠比例 <span class=\"inline-math\">r</span> 直接换取接缝质量与算力开销，材料未给出该比例，落地时需按分辨率档位标定。</p>\n<p>失效条件集中在三处。其一，块过大触发显存溢出回退到更小分块，回退本身改变块数与重叠结构，使原本标定的尺度表与调度失配，属于典型的分块溢出失败模式；回退次数应作为一级监控指标。其二，低比特激活在时空注意力输入处引入量化误差，长视频下误差沿时间维累积，重叠区正是误差跨块传递的通道，材料未给出误差上界或补偿机制，故长视频、高分辨率、大重叠比例三者叠加时风险最高。其三，少步蒸馏压缩了采样轨迹，与低比特量化叠加可能同时损失细节与运动多样性，需分别评估而非合并归因。</p>\n<p>可复算的预算示例：给定 <span class=\"inline-math\">N_b</span>、<span class=\"inline-math\">E_b</span>、<span class=\"inline-math\">a</span>、<span class=\"inline-math\">r</span> 与组数，按上式逐项相加即得激活账本，再叠加权重与解码器驻留即得峰值；HBM3e 容量核算只需把峰值与单卡容量比较，超出即触发回退。由于材料未给出比特位宽、分组大小、重叠比例与硬件档位，上述预算只能作为容量标定的骨架：部署时须以实测的每块去噪时延、VAE 解码时延与溢出告警反推 <span class=\"inline-math\">N_b</span> 上限，并把首块输出时延与整段完成时延共同纳入 SLO，而非仅看单块吞吐。</p>\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-28\">二十八 · 从“逐块去噪”到可调度的工作单元</h3>\n<p>Q-VDiT 的推理形态决定了调度器的基本粒度：一次请求先编码条件、初始化 latent，再按时间块切分为去噪单元，每块独立执行时空注意力与 MLP，块间保留重叠区供 VAE 解码拼接。这意味着调度器面对的既不是 LLM 那种“一个 token 一步”的细粒度流，也不是整段视频一次性吃进显存的粗粒度批，而是<strong>块级（chunk-level）工作单元</strong>。块大小直接决定三件事：单块激活显存、单块去噪时延、以及块间可并行的空隙。块过大触发显存溢出回退到更小分块，这本身就是一次调度失败——回退意味着重新切分、重新分配激活缓存，已完成的块无法回滚，尾延迟被硬生生拉长。因此调度器的第一职责不是“凑批”，而是<strong>在显存预算内把块切成稳定尺寸</strong>，把回退次数压到零。</p>\n<p>把块视为工作单元后，连续批处理（continuous batching）才有落点：新请求到达时不必等当前批整体结束，而是把它的首块插入正在运行的块队列，与其它请求的中间块混跑。代价是激活缓存必须按块而非按请求分配，块的生命周期短、释放频繁，分配器的碎片率上升。工程上通常给块缓存设一个上限 <em>B<sub>max</sub></em>，同时在处理的块数 <em>n</em> 满足：</p>\n<div class=\"formula\">$$n \\cdot \\big(M_{\\text{act}}^{\\text{chunk}} + M_{\\text{kv}}^{\\text{chunk}}\\big) \\le M_{\\text{budget}} - M_{\\text{static}}$$</div>\n<p>其中 <em>M<sub>static</sub></em> 是权重与量化尺度常驻部分。这个不等式是调度器的硬约束：它决定了并发请求数的上限，也决定了块大小能否调大。举例说，一条 720p、数十帧的请求若按较大时间块切分，单块激活就吃掉预算的大头，此时连续批处理只能退化为“单请求多块流水”，并发度被显存而非算力卡住——这正是视频 DiT 与文本 LLM 调度最本质的差别。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-29\">二十九 · chunked prefill 在视频 DiT 里的对应物</h3>\n<p>LLM 的 chunked prefill 是把长 prompt 的预填切成若干段与解码请求混批，以压平首 token 时延的尖峰。视频 DiT 没有严格意义上的 prefill/decode 二分，但有结构同构的阶段：<strong>条件编码与首块去噪</strong>相当于“重计算前置段”，<strong>后续块去噪</strong>相当于“稳态推进段”。首块要建立跨帧时间注意力的初始状态、激活离群值最集中，单块时延显著高于后续块；若把首块与稳态块混在同一批里，整批时延被首块拖住，尾延迟恶化。可行的做法是把首块单独成批、优先调度，稳态块走连续批处理——即“前置段独占、稳态段混跑”的两级队列。</p>\n<p>更细一层，块内还可按去噪步做切分。学生网络经蒸馏后步数少于教师，但每步仍是一次完整前向；若把同一块的连续步视为不可分割单元，调度器就失去了在步间插入其它块的机会。把“块×步”作为可抢占点，能让高优先级请求在步边界插入，代价是每步都要保存/恢复该块的 latent 与量化尺度状态。伪代码思路：</p>\n<ul>\n<li>队列按 (请求优先级, 块序号) 排序，首块永远优先于任何稳态块；</li>\n<li>每个调度周期取 <em>n</em> 个块组成一批，批内块大小取齐以避免张量核心空转；</li>\n<li>步边界检查抢占标志，若高优先级请求到达则当前块让出，状态写入块缓存；</li>\n<li>块完成后立即释放激活缓存，仅保留重叠区 latent 供 VAE 拼接。</li>\n</ul>\n<p>这套机制的吞吐代价是可计算的：步边界抢占引入的状态换入换出按块计，若每块每步都换出，带宽开销与激活规模同阶，等于把省下的算力又还给了显存带宽。因此抢占粒度应设在块边界而非步边界，除非 SLO 明确要求首块时延。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-30\">三十 · 优先级、抢占与尾延迟的压缩</h3>\n<p>视频生成的 SLO 是双指标的：首块输出时延（用户看到第一段画面的时间）与整段完成时延。前者决定交互感，后者决定批处理吞吐。二者在调度上直接冲突——优先首块意味着频繁打断稳态批，稳态批的完成时间被拉长，尾延迟（p99）上升。压尾延迟的工程手段不是调优先级数值，而是<strong>限制抢占频率与抢占深度</strong>：给每个请求设一个“已让出次数”上限，超过上限的请求不再被抢占，避免长请求在队列里反复被打断而永远完不成。</p>\n<p>量化侧还带来一个调度耦合：激活量化尺度按时间步与块更新，抢占后恢复必须带着尺度状态一起换入，否则块边界处的量化误差会跳变，长视频下沿时间维累积。这意味着抢占不是无状态的操作，块缓存里必须存 <em>s<sub>t</sub></em> 的当前值。代价是块缓存的元数据膨胀，若块数多、尺度按分组存储，元数据本身可能占用可观显存。工程判断：在低比特激活方案下，抢占应尽量少发生，宁可让首块独占一个短周期，也不要频繁换出带尺度状态的块。</p>\n<p>具体例子：一个混跑场景里，三条长视频请求与若干短请求并发。若短请求每到达就抢占，长请求的块在队列中反复进出，其重叠区 latent 的量化尺度状态被反复重建，块间接缝处的误差累积风险上升；反之若把短请求集中在一个调度窗口内批量插入，长请求的稳态推进不被打断，整段完成时延的 p99 反而更可控。这是“少抢占、集中插入”的典型取舍。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-31\">三十一 · 分离式预填/解码在分块流式里的映射</h3>\n<p>分离式预填/解码（disaggregated prefill/decode）在 LLM 里是把计算密集的预填与带宽密集的解码放到不同资源池，避免二者互相挤占。Q-VDiT 的结构天然支持一种同构分离：<strong>去噪阶段</strong>是算力与激活显存密集的（时空注意力 + 低比特张量核心），<strong>VAE 解码阶段</strong>是带宽与显存密集的（按块流式解码、块间重叠拼接）。材料明确写了“VAE 解码与去噪阶段分离以控制峰值显存”，这正是分离式部署的机制基础。</p>\n<p>把两阶段放到不同执行单元后，去噪侧可以维持稳定的块批，解码侧按块到达顺序流式消费，二者通过块队列解耦。峰值显存的表达式变为两侧之和而非串行叠加：</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx M_{\\text{denoise}}(n) + M_{\\text{vae}}(k) + M_{\\text{handoff}}$$</div>\n<p>其中 <em>k</em> 是解码侧同时在解的块数，<em>M<sub>handoff</sub></em> 是块队列中待解码 latent 的驻留量。分离的收益是去噪侧不必为 VAE 的瞬时峰值让路，块大小可以调大、批可以更满；代价是 handoff 队列成为新的背压点——解码慢于去噪时队列积压，显存被待解码 latent 吃掉，最终仍会触发溢出回退。因此分离式部署必须给 handoff 队列设硬上限，并在积压时反压去噪侧降低块并发。这是分离式架构里最容易被忽略的容量约束。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-32\">三十二 · 时延与吞吐的取舍线画在哪里</h3>\n<p>把上述机制合起来看，Q-VDiT 在 Blackwell 上的调度取舍可以归结为三个可调旋钮：块大小、并发块数、抢占策略。块大小增大提升张量核心利用率与单块吞吐，但压缩并发块数、抬高单块时延与溢出风险；并发块数增大提升整体吞吐，但激活缓存碎片与 handoff 积压同步上升；抢占越激进首块时延越低，稳态批的尾延迟越差。三者不存在同时最优，工程上应<strong>先按 SLO 定块大小上限，再用并发块数填满显存预算，最后用最小抢占满足首块时延</strong>。</p>\n<p>低比特量化与少步蒸馏改变了这条取舍线的位置：量化压低激活显存，使同样预算下能容纳更多块，吞吐上限上移；蒸馏减少步数，使单块时延下降，首块时延更容易达标。但两者叠加的失败模式是细节与运动多样性同时损失，调度层面表现为“块推进很快但块间接缝明显”——这不是调度能修的，只能靠块重叠比例与量化尺度的时间一致性约束去压。容量标定时应把“块溢出回退次数”和“handoff 队列积压深度”作为一等监控指标，而不是只看端到端时延均值；均值好看而 p99 被回退拖垮，是这类分块流式系统最典型的容量误判。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-33\">三十三 · 分块流式下的调度边界：为什么这套方案没有连续批处理的位置</h3>\n<p>Q-VDiT 的推理组织方式决定了它天然落在“静态分块、单请求流式”这一侧：latent 按时间块切分后逐块去噪，块间保留重叠区供 VAE 解码拼接，显存峰值由同时在处理的块数与激活缓存共同决定。这个结构里没有 token 级的可变序列长度，也没有可被连续批处理拼接的独立请求单元——一个请求的块必须按时间顺序推进，块 k+1 的去噪依赖块 k 输出的 latent 上下文。因此 vLLM 式连续批处理、chunked prefill 那套“把新请求的 prefill 切碎塞进 decode 空隙”的调度在这里失效，因为不存在 prefill/decode 两相分离：每一块既是“预填”也是“解码”。真正可调度的自由度只有三个：并发请求数、每请求的分块大小、以及块间重叠比例。三者共同约束显存峰值，块过大触发溢出回退到更小分块，回退本身会打断流式节奏并拉高首块时延。</p>\n<p>把这条约束写成容量判断：设单块激活缓存为 $M_{\\text{blk}}$、并发请求数为 $N$、重叠区缓存为 $M_{\\text{ovl}}$，则峰值显存近似 $M_{\\text{peak}} \\approx N\\cdot(M_{\\text{blk}}+M_{\\text{ovl}}) + M_{\\text{w}}$，其中 $M_{\\text{w}}$ 为分组量化权重与低比特算子工作区。由于 $M_{\\text{blk}}$ 随分辨率与帧数增长而非线性增长（时空注意力激活规模随块内帧数平方级膨胀），$N$ 与块大小是互斥的：想提高吞吐就得压块大小，代价是重叠区占比上升、VAE 拼接次数增多、单位像素的解码开销变大。这是典型的吞吐—尾延迟对冲，而不是可以通过批调度抹平的排队问题。</p>\n<table class=\"mini\"><thead><tr><th>调度自由度</th><th>对吞吐</th><th>对尾延迟</th><th>失效条件</th></tr></thead><tbody><tr><td>并发请求数 N</td><td>线性上升直至显存饱和</td><td>饱和后排队，首块时延抬升</td><td>N·M_blk 逼近显存上限</td></tr><tr><td>分块大小</td><td>增大则单块算力密度升、块数降</td><td>增大则单块时延升、回退风险升</td><td>块溢出触发回退</td></tr><tr><td>重叠比例</td><td>增大则有效吞吐降</td><td>增大则接缝误差降但解码次数升</td><td>长视频下重叠区误差累积</td></tr></tbody></table>\n<p>尾延迟的真正来源不是排队，而是两处不可预测的放大：一是量化误差沿时间维累积，长视频后段的激活离群值被时间一致性尺度压制得不充分时，去噪质量下降会迫使运维侧调大重叠比例或回退分块，间接拉长整段完成时延；二是少步蒸馏把采样步数压到很少后，单块内每一步的算力占比上升，任何一次显存溢出回退都会让该块时延出现阶跃而非渐变。工程上的压尾手段因此不是优先级抢占（没有可抢占的独立单元），而是预算化的准入控制：按 $N \\le \\lfloor (M_{\\text{budget}}-M_{\\text{w}})/(M_{\\text{blk}}+M_{\\text{ovl}}) \\rfloor$ 静态限流，并对长视频请求预留更大的重叠区预算，把回退次数作为一级监控指标而非事后告警。分离式预填/解码在这套结构里同样无处落地——VAE 解码已与去噪阶段分离并按块流式进行，但两者共享同一 latent 时间轴，跨卡切分需按时间维评估通信代价，材料未给出并行拓扑，容量判断只能停在机制层面。</p>\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-34\">三十四 · 并行拓扑的切分维度与视频 DiT 的映射</h3>\n<p>视频扩散 Transformer 的并行切分不能照搬语言模型的直觉。语言模型按 token 维做张量并行（TP）时，序列维天然连续且长度可控；视频 DiT 的 latent 是时空四维张量，时间维与空间维的语义权重不同，切分维度直接决定跨卡通信的形态。Q-VDiT 的推理链按时间块组织去噪，这给并行拓扑提供了一个天然的切分锚点：<strong>时间维切分（序列并行/上下文并行）</strong>把不同时间块分配到不同 rank，跨帧时间注意力需要在这些块之间交换键值；<strong>空间维切分</strong>把单帧内的 patch 网格拆开，时空注意力的局部窗口可以留在卡内，但跨窗口的全局注意力仍需集合通信；<strong>TP</strong> 切在注意力头与 MLP 隐藏维上，每层前后各一次 All-Reduce；<strong>EP</strong> 对 DiT 意义有限，因为视频 DiT 主干通常不含 MoE，只有在把条件编码器或 VAE 解码器做成专家并行时才有意义；<strong>PP</strong> 按层切分，流水气泡在少步采样下被放大——学生步数少意味着每步的前向更短，PP 的填充/排空占比上升，收益被稀释；<strong>DP</strong> 复制整模型、按请求切分，是并发吞吐的首选，但单请求时延不受益。</p>\n<p>切分选择的代价可以直接写成通信量估算。设单层注意力输入激活为 <span class=\"inline-math\">A</span>（字节），TP 度为 <span class=\"inline-math\">t</span>，则每层两次 All-Reduce 的通信量为</p>\n<div class=\"formula\">$$V_{\\mathrm{TP}} = 2 \\cdot \\frac{t-1}{t} \\cdot |A| \\cdot B$$</div>\n<p>其中 <span class=\"inline-math\">B</span> 为批内 token 数。时间维切分的代价则是跨块键值交换：若每块有 <span class=\"inline-math\">n_k</span> 帧、每帧 <span class=\"inline-math\">n_p</span> 个 patch、头维 <span class=\"inline-math\">d</span>，跨帧注意力需要 All-to-All 交换 KV，量级为 <span class=\"inline-math\">\\(O(n_k \\cdot n_p \\cdot d)\\)</span> 每层每头。具体例子：一个按时间块切到 4 卡的配置，块间重叠区用于 VAE 拼接，重叠区越大，跨卡交换的 KV 越多，且重叠区的量化误差还会沿时间维累积——这正是 Q-VDiT 分块流式解码在并行化后暴露的新代价。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-35\">三十五 · NVLink 5 与 NVSwitch：集合通信的物理底座</h3>\n<p>Blackwell 档位的机内互联把集合通信的瓶颈从“链路带宽”推向“协议开销与拓扑映射”。GB200/GB300 NVL72 以 NVLink 5 域配合 NVSwitch 构成全互联的 scale-up 域，单跳延迟低、All-Reduce 可走硬件多播路径；跨机架则退回 InfiniBand 或以太网，带宽与延迟差一个档位。工程含义是：<strong>TP 与 EP 必须留在 NVLink 域内</strong>，一旦 TP 跨机架，每层两次 All-Reduce 的延迟会直接吃掉少步采样的时延预算；<strong>DP 与 PP 可以跨机架</strong>，因为它们的通信频次低（DP 只在梯度/参数同步时有量，推理侧几乎为零；PP 只在层边界传激活）。</p>\n<p>对视频 DiT 而言，激活体量远大于语言模型：一个时间块的时空注意力激活在低比特下仍需按块驻留显存。NVLink 5 的高带宽使得“把激活切到多卡再集合”在带宽上可行，但 All-Reduce 的算法开销（ring 的 <span class=\"inline-math\">2(t-1)/t</span> 因子）在小消息下由延迟主导。判断准则：当单次集合通信的消息小于某阈值时，ring 不如递归倍增或 NVSwitch 硬件归约；Q-VDiT 的少步学生每步前向短，单层激活的通信窗口更窄，更容易落入延迟主导区。这是“通信什么时候成为瓶颈”的第一条判据——<strong>消息尺寸与步数共同决定通信是否可被计算掩盖</strong>。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-36\">三十六 · All-to-All 与 All-Reduce 的代价分工</h3>\n<p>两类集合通信在视频 DiT 推理中承担不同角色，不能混为一谈。All-Reduce 服务于 TP：每层注意力的输出投影与 MLP 下投影后各一次，把分片的部分和归约成完整激活。All-to-All 服务于时间维/序列并行：跨帧时间注意力需要把各卡的 KV 重排到需要它们的卡上，本质是“按注意力配对关系做数据重分布”。All-to-All 的代价对负载均衡极其敏感——若各时间块的帧数不均（长视频尾块通常更短），部分 rank 会空等，有效带宽下降。</p>\n<p>把两者放进同一条推理链，可以得到一个粗略的每步通信占比：设单步计算时间为 <span class=\"inline-math\">\\(T_{\\mathrm{comp}}\\)</span>，TP 的 All-Reduce 时间为 <span class=\"inline-math\">\\(T_{\\mathrm{AR}}\\)</span>，时间并行的 All-to-All 时间为 <span class=\"inline-math\">\\(T_{\\mathrm{A2A}}\\)</span>，则通信可被掩盖的条件是</p>\n<div class=\"formula\">$$T_{\\mathrm{comp}} \\ge T_{\\mathrm{AR}} + T_{\\mathrm{A2A}}$$</div>\n<p>在低比特张量核心把 <span class=\"inline-math\">\\(T_{\\mathrm{comp}}\\)</span> 压短之后，这个不等式更容易被打破——量化提升算力密度，反而把瓶颈推向通信。具体例子：一个 W4A4 的时空注意力层，张量核心完成矩阵乘的时间被压缩，而跨帧 KV 的 All-to-All 消息尺寸不随比特位宽缩小（KV 仍按块驻留），于是通信占比上升。这解释了为什么低比特推理的并行策略必须重新标定，而不能沿用全精度时代的 TP 度。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-37\">三十七 · NIXL 传输：分离式预填/解码与块级流式</h3>\n<p>NIXL 面向的是跨节点、跨存储层的数据搬运，在视频生成推理里的落点是<strong>去噪与 VAE 解码的分离部署</strong>。Q-VDiT 的推理结构本身就把 VAE 解码与去噪阶段分离、按块流式解码；当去噪集群与解码集群不在同一节点时，块级 latent 需要从去噪 rank 传到解码 rank。NIXL 的价值在于把这段传输做成异步、零拷贝的块级流水：去噪完成一块即发起传输，解码端按到达顺序拼接重叠区，显存峰值由“同时在处理的块数”而非整段视频决定。</p>\n<p>代价分析：块级传输的带宽需求为 <span class=\"inline-math\">\\(R = \\frac{|z_{\\mathrm{block}}|}{\\tau_{\\mathrm{denoise}}}\\)</span>，其中 <span class=\"inline-math\">\\(|z_{\\mathrm{block}}|\\)</span> 是单块 latent 字节数，<span class=\"inline-math\">\\(\\tau_{\\mathrm{denoise}}\\)</span> 是该块去噪耗时。若去噪被少步蒸馏压缩，<span class=\"inline-math\">\\(\\tau_{\\mathrm{denoise}}\\)</span> 变小，所需传输带宽反而上升——少步化把压力从计算转移到搬运。工程判断：分块大小是这条链上的关键旋钮，块过大触发显存溢出回退到更小分块，块过小则传输次数增多、NIXL 的每消息开销占比上升。重叠区的存在进一步放大了传输量，因为重叠帧要被两边各算一次、各传一次。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-38\">三十八 · 通信成为瓶颈的判据与容量标定</h3>\n<p>把前述机制收敛成可操作的判据，通信成为瓶颈通常出现在三种情形。其一，<strong>TP 度超过 NVLink 域</strong>：每层 All-Reduce 的延迟不再被计算掩盖，少步采样下每步预算更紧，跨机架 TP 直接不可行。其二，<strong>时间维切分导致 All-to-All 负载不均</strong>：长视频尾块短、重叠区重复计算，rank 间空等使有效吞吐低于线性扩展。其三，<strong>块级传输带宽跟不上少步去噪</strong>：NIXL 搬运成为端到端时延的主项，尤其当 VAE 解码与去噪分离部署且解码吞吐与分辨率不匹配时。</p>\n<p>容量标定的做法是分层测量而非整体猜测：先固定单卡分块流式的每块去噪时延与 VAE 解码时延（材料未给出具体数值，需实测），再按 TP 度扫描 All-Reduce 占比，按时间切分度扫描 All-to-All 空等率，最后按 NIXL 带宽反推可支撑的块并发数。监控指标应包含每块去噪时延、块间传输时延、集合通信等待时间占比与显存溢出回退次数。Q-VDiT 材料未给出并行拓扑与 SLO 实测，因此上述标定只能停在机制层面；但机制本身给出了明确的工程判断：<strong>低比特把计算压短，少步把每步预算压紧，两者叠加使并行策略的可行域收窄，TP 应尽量留在单机 NVLink 域内，跨机扩展优先走 DP 与块级流水而非切分注意力</strong>。</p>\n<p>最后落在具体机制上：时间一致性量化算子的尺度按时间步与块更新，这意味着不同 rank 上的块可能持有不同的量化尺度；当跨卡交换 KV 时，尺度不一致会引入额外的反量化/再量化步骤，这部分开销不在集合通信的带宽账上，却真实占用流水线。并行设计必须把量化尺度的同步或对齐纳入通信预算，否则低比特的收益会在跨卡边界处被悄悄抵消。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-39\">三十九 · 分块流式推理下的并行拓扑边界：通信何时压过计算</h3>\n<p>Q-VDiT 的推理形态决定了它对并行切分的敏感点与常规大模型服务不同：去噪单元是时间块而非整段序列，块间还保留重叠区供 VAE 拼接，因此 TP/EP/PP/DP 四种切分在这里的代价结构必须按“块内计算—块间流水—解码拼接”三段来算。块内时空注意力的激活规模由块大小与分辨率决定，单卡即可容纳时，TP 的 All-Reduce 只会把本可本地完成的注意力拆成跨卡规约，NVLink 5 的带宽再高也换不回被切碎的算子融合收益；反之，当块被放大到显存上限、激活缓存逼近预算时，TP 才成为把单块摊到多卡的唯一手段。EP 在视频 DiT 上缺少天然专家路由，强行引入只会带来 All-to-All 的额外跳数；PP 则与分块流式天然契合——把不同时间块分给不同流水段，段间只传 latent 而非激活，通信量按块边界计，远小于层内切分。判断准则可以写成块内计算时间与跨卡通信时间的比值：</p>\n<div class=\"formula\">$$\\rho=\\frac{T_{\\mathrm{blk}}}{T_{\\mathrm{comm}}}=\\frac{F_{\\mathrm{blk}}/\\mathrm{TFLOPS}_{\\mathrm{eff}}}{B_{\\mathrm{blk}}/\\mathrm{BW}_{\\mathrm{link}}}$$</div>\n<p>其中 $F_{\\mathrm{blk}}$ 是单块在低比特张量核心上的有效浮点工作量，$B_{\\mathrm{blk}}$ 是切分后需跨卡搬运的字节数。$\\rho$ 明显大于 1 时切分是净收益；$\\rho$ 接近或小于 1 时，通信开始主导每块时延，而此时 SLO 衡量的恰恰是首块输出时延——首块被通信拖慢，流式返回的启动时间直接劣化。以 GB200 NVL72 机架为例，NVSwitch 让机架内 All-Reduce 与 All-to-All 走统一交换结构，单跳延迟低但集合通信的同步屏障仍会放大块间抖动；当并发请求按块调度、每块都要做一次规约时，抖动沿块序列累积，整段完成时延的方差比均值更值得监控。NIXL 在这里的角色是块间 latent 与重叠区数据的点对点搬运，它绕开集合通信的同步语义，适合 PP 段间传递与跨节点 VAE 解码拼接；但 NIXL 传输的是已量化或已解码的块数据，若块边界处的量化误差未被时间一致性尺度压住，传输本身不会引入误差，误差是在块内注意力输入处产生的，跨卡只是把它原样带过去。</p>\n<p>失效条件集中在三处。其一，块过大触发显存溢出回退到更小分块时，切分方案必须同步重算：块变小意味着 $\\rho$ 中的 $F_{\\mathrm{blk}}$ 缩小而通信字节未必等比缩小，原本划算的 TP 度可能瞬间变成瓶颈，回退逻辑若只改块大小不改并行度，就会出现“算得动但传不动”的块。其二，长视频下低比特激活误差沿时间维累积，重叠区是唯一能吸收边界误差的缓冲，但重叠比例材料未给出，若重叠区本身也被切分到不同卡上，误差校正就失去了本地性，此时应优先保证重叠区落在同一设备内。其三，少步蒸馏压缩了每块的去噪步数，单块计算时间随之缩短，$\\rho$ 的分子变小，通信占比被动上升——蒸馏越激进，并行切分的收益窗口越窄，这是 Q-VDiT 与常规服务在容量规划上的关键差异。功耗侧同样有代价：机架内高频集合通信与张量核心满载叠加时，NVLink 与交换芯片的功耗预算需与计算功耗一并计入单机架容量，材料未给出档位实测，只能按机制定性判断通信密集配置会压缩可部署的并发块数。</p>\n<table class=\"mini\"><thead><tr><th>切分方式</th><th>在本方案中的适配点</th><th>主要代价</th></tr></thead><tbody><tr><td>PP（按时间块）</td><td>段间只传 latent，与流式解码顺序一致</td><td>流水气泡落在首块启动，影响首块时延</td></tr><tr><td>TP（块内）</td><td>块放大到显存上限时摊薄激活</td><td>每块一次 All-Reduce，$\\rho$ 随蒸馏步数下降</td></tr><tr><td>EP</td><td>无天然路由，仅作容量兜底</td><td>All-to-All 跳数增加，收益不明</td></tr><tr><td>DP（按请求）</td><td>并发请求各自分块，互不通信</td><td>显存峰值按副本数线性增长</td></tr></tbody></table>\n<p>工程判断落在调度器的一个约束上：把并行度选择绑定到块大小与蒸馏步数的联合配置，而不是按模型参数量静态设定。具体做法是在容量标定时对每个候选块大小测出 $T_{\\mathrm{blk}}$ 与 $T_{\\mathrm{comm}}$，只保留 $\\rho$ 超过阈值的切分组合，并把块溢出回退次数作为并行度重算的触发信号；跨节点场景优先用 NIXL 承载块间与解码拼接的数据面，把集合通信限制在必须同步的层内规约上。材料未给出硬件档位与 SLO 实测，因此这套判据只能作为机制层面的准入条件，实际部署仍需按分块上限、量化方案与并发块数逐档标定，任何脱离块级测量的并行度设定都不具备可复核性。</p>\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-40\">四十 · 精度塌陷的三种形态与量化误差的时间维指纹</h3>\n<p>在 Q-VDiT 的推理链上，精度塌陷不是单一现象，而是三种可区分形态的叠加。第一种是<strong>块内塌陷</strong>：某一时间块的激活在时空注意力输入处被量化算子裁剪后，跨帧离群值被压平，导致该块内运动细节丢失，表现为块内帧间位移场变平、纹理高频成分消失。第二种是<strong>块间漂移</strong>：由于量化尺度按时间步与块更新，相邻块若尺度跳变过大，重叠区拼接时出现亮度或色度台阶，这是分块流式解码特有的失败形态。第三种是<strong>尾块累积塌陷</strong>：长视频后段块的条件信息已被前块潜变量稀释，低比特误差沿时间维单向累积，尾块质量显著劣于首块。</p>\n<p>诊断这三种形态，关键是把量化误差从“整段 FVD”拆到“逐块统计量”。量化算子对激活做 <span>clip(A/s_t)·s_t</span>，其中尺度 s_t 按时间步与块更新；因此可监控的量是每块的<strong>裁剪比例</strong>（被 clip 截断的元素占比）与<strong>反量化残差</strong>（‖Â−A‖ 的块均值）。块内塌陷对应裁剪比例突升；块间漂移对应相邻块残差均值的阶跃；尾块累积对应残差沿块序号的单调上升趋势。这三条曲线比端到端指标更早暴露问题，且不需要参考视频。</p>\n<div class=\"formula\">$$r_b=\\frac{1}{|\\mathcal{B}_b|}\\sum_{i\\in\\mathcal{B}_b}\\left\\|\\hat{A}_i-A_i\\right\\|_2,\\qquad \\Delta_b=\\left|r_b-r_{b-1}\\right|$$</div>\n<p>系统代价上，逐块残差统计本身要在去噪循环里插入一次归约，代价是每块一次全块扫描的带宽开销；在激活缓存本就吃紧的分块流式路径上，这会挤占本已紧张的显存带宽。工程折中是只对注意力输入做采样统计（按固定间隔抽元素），把监控开销压到可忽略，但代价是尾块累积趋势的检测灵敏度下降。具体例子：一段按时间块切分的 latent 序列，若第 3 块裁剪比例从基线水平跳到接近全块被截断，而同块反量化残差同步抬升，则几乎可以断定该块的 s_t 被前一时刻的离群值带偏，应触发尺度重校准而非整段回滚。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-41\">四十一 · OOM 与分块溢出回退：峰值显存的账怎么算</h3>\n<p>Q-VDiT 的显存峰值由“同时在处理的块数 × 单块激活缓存”决定，而不是由整段视频长度决定——这正是分块流式设计的初衷。但 OOM 仍会发生，且发生位置有规律：一是<strong>块过大</strong>，单块时空注意力激活超出预算，触发回退到更小分块；二是<strong>重叠区缓存叠加</strong>，块间重叠区供 VAE 解码拼接，若重叠比例设置偏大，解码阶段会同时持有两块的重叠潜变量与解码中间结果；三是<strong>去噪与解码未真正分离</strong>，若调度器让下一块去噪与上一块 VAE 解码并发，峰值是两者之和而非最大值。</p>\n<p>定位 OOM 的正确做法是给显存峰值建一个可加模型，而不是看 nvidia-smi 的瞬时值。把峰值拆成四项：当前块激活、重叠区潜变量、VAE 解码工作集、量化算子临时缓冲。回退逻辑应绑定到“块大小”这一个旋钮上，因为其余三项都由块大小与重叠比例派生。伪代码思路是：在块调度前用上一块的实测峰值外推下一块，若超过预算的设定比例则预降块大小，而不是等分配失败再回退——后者会让回退本身成为尾延迟来源。</p>\n<table class=\"mini\"><thead><tr><th>峰值构成</th><th>随什么变化</th><th>回退手段</th><th>副作用</th></tr></thead><tbody><tr><td>单块激活缓存</td><td>块大小、分辨率</td><td>缩小分块</td><td>块数增加、块间漂移风险上升</td></tr><tr><td>重叠区潜变量</td><td>重叠比例</td><td>降重叠比例</td><td>拼接接缝变明显</td></tr><tr><td>VAE 解码工作集</td><td>解码分辨率、并发解码块数</td><td>串行化解码</td><td>首块输出时延上升</td></tr><tr><td>量化临时缓冲</td><td>分组大小、比特位宽</td><td>调分组</td><td>量化粒度变粗、精度下降</td></tr></tbody></table>\n<p>代价判断：缩小分块能解 OOM，但块数上升会放大块间漂移与尾块累积，等于用精度换显存；降重叠比例省显存但直接损伤拼接质量。因此 OOM 回退不能只追求“跑通”，必须同时记录回退次数与回退后的逐块残差，否则会把一次显存事故悄悄转化成一次质量事故。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-42\">四十二 · 批抖动与尾延迟：少步调度下的方差来源</h3>\n<p>少步蒸馏把学生步数压到远少于教师，这改变了延迟的构成：单请求的去噪步数变少，单步的相对权重变大，任何一步的抖动都会直接反映到端到端时延上。批抖动在 Q-VDiT 上有三个来源。其一是<strong>块大小不均</strong>：不同时间块的激活规模随内容变化（高运动块激活离群值更多、裁剪更频繁），导致同批内各块的张量核心占用不均。其二是<strong>量化尺度的动态更新</strong>：尺度按时间步与块更新，若更新路径上出现分支或同步点，会引入不可预测的停顿。其三是<strong>解码与去噪的耦合</strong>：VAE 解码按块流式进行，若解码吞吐与去噪吞吐不匹配，解码会成为背压源，反过来拉长去噪块的驻留时间。</p>\n<p>尾延迟的监控不能只看均值。应以“首块输出时延”和“整段完成时延”两个 SLO 分别建分布，并对块级时延做分位数统计：若 P99 块时延显著偏离 P50，且偏离集中在特定块序号区间，则指向尾块累积或重叠区缓存争用；若偏离随机分布，则指向批内块大小不均导致的张量核心利用率抖动。诊断手段是把每块去噪时延、VAE 解码时延、量化算子耗时分别打点，形成块级时间线，而不是只留一个端到端数字。</p>\n<p>具体例子：并发请求下按块调度，若某请求的首块因等待前序请求释放激活缓存而延迟，其后续块会连锁推迟，整段完成时延的尾部分位数被放大——这是分块流式与批调度耦合的典型尾延迟放大效应。缓解方向是给首块以更高调度优先级并预留最小激活预算，代价是并发度上限下降。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-43\">四十三 · 静默降级：没有报错的质量衰减怎么抓</h3>\n<p>最危险的失败模式不是 OOM 也不是超时，而是系统一切正常、指标一切正常，但输出质量已经降级。Q-VDiT 的静默降级有三条典型路径。第一条是<strong>量化尺度漂移</strong>：s_t 在训练后固定，但推理时输入分布偏移（更长视频、更高运动）使裁剪比例缓慢上升，系统不报错，只是细节逐步变糊。第二条是<strong>回退链的隐性触发</strong>：OOM 回退到更小分块后请求成功返回，但块间漂移未被检测，用户拿到的是拼接痕迹更重的视频。第三条是<strong>少步蒸馏的多样性损失</strong>：学生步数少于教师，运动多样性本就可能被削弱，若再叠加低比特量化，输出会趋于保守，而这一损失不体现在任何时延或显存指标上。</p>\n<p>抓静默降级需要与请求内容无关的<strong>在线探针</strong>：在固定间隔注入一条已知条件的探针请求，走完整推理链，比对探针输出的逐块残差、帧间位移统计与纹理能量，与基线快照做漂移检测。探针的代价是占用少量推理容量，但它是唯一能在无参考视频条件下发现质量漂移的手段。另一条低成本路径是把逐块裁剪比例与反量化残差做成常驻告警阈值：裁剪比例越过设定线即标记该请求为“降级可疑”，在返回结果的同时写入诊断标签，供离线复核。</p>\n<p>工程判断上，静默降级的处置优先级应高于 OOM：OOM 是显性失败，可重试、可回退、可告警；静默降级是隐性失败，用户拿到的是“成功”的坏结果，污染的是信任而非可用性。因此监控体系里必须有一条与吞吐、时延并列的质量漂移指标，且该指标要能按块序号定位，否则无法区分是全局量化方案退化还是局部分块边界问题。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-44\">四十四 · 回滚策略：按失败模式分层，而不是整段重跑</h3>\n<p>回滚在 Q-VDiT 上不能是“整段重新生成”，因为整段重跑的代价是数倍的首块时延与显存峰值，且会掩盖真正的失败根因。正确做法是按失败模式分层回滚，粒度对齐到块与算子。</p>\n<ul>\n<li><strong>块级回滚</strong>：检测到某块裁剪比例或残差越线，仅对该块以更高精度（放宽量化或提高尺度更新频率）重算，重叠区随之重解码。代价是单块重算时延，收益是避免整段重跑。</li>\n<li><strong>尺度回滚</strong>：若漂移是全局性的（多块同步越线），回退到上一版校准的 s_t 快照，并冻结尺度更新直至探针恢复。代价是量化收益暂时下降。</li>\n<li><strong>分块策略回滚</strong>：若 OOM 回退次数在窗口内超阈值，回退到更保守的默认块大小与重叠比例，并把该档位写入容量配置，而不是每次请求临时试探。</li>\n<li><strong>步数回滚</strong>：若多样性探针显示运动退化，临时提高学生步数（向教师调度靠拢），代价是采样时延上升，作为质量兜底而非常态。</li>\n</ul>\n<p>回滚的触发必须绑定可观测信号而非人工判断，且每次回滚要记录“触发信号—回滚层级—回滚后逐块残差”，形成闭环。具体例子：长视频请求在尾块出现残差单调上升，块级回滚对尾块重算后残差回落，但若下一请求在同位置再次越线，则说明是分块边界的时间一致性误差而非偶发离群值，应升级为分块策略回滚并调整重叠比例，而不是反复做块级重算。</p>\n<p>容量规划的含义是：回滚能力本身要占预算。为块级重算预留的算力、为探针预留的容量、为更高精度回滚预留的显存余量，都应在 SLO 容量模型里显式计入，否则回滚会在高峰时段变成不可用功能。Q-VDiT 把低比特量化与少步蒸馏放在同一条推理链上，意味着精度与步数两个旋钮都可回滚，但也意味着回滚组合数上升——工程上应把回滚策略收敛为有限档位，每档对应明确的块大小、量化方案与步数调度，避免运行时做无界试探。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-45\">四十五 · 分块流式链路上的失效面：从量化溢出到静默降级</h3>\n<p>Q-VDiT 的推理形态决定了它的失败不是单点故障，而是沿“量化算子—时间块—VAE 拼接”三段串联放大。第一段是量化溢出：注意力输入处的激活经 <span class=\"formula\">$$\\hat{A}=\\mathrm{clip}(A/s_t)\\cdot s_t$$</span> 裁剪，尺度 <span class=\"formula\">$$s_t$$</span> 按时间步与块更新；当某块的跨帧离群值超出该尺度覆盖范围，裁剪即变成硬截断，误差不会在本块内暴露，而是以潜变量的形式传给下一块。长视频下这种误差沿时间维单调累积，表现为后段画面细节漂移、运动连贯性下降，而首块输出完全正常——这是最典型的“静默降级”：SLO 的首块时延达标，整段完成时延也达标，只有画质在尾段塌陷。诊断手段是在每个块的量化算子出口挂激活绝对值直方图与裁剪比例计数器，把“裁剪比例超过阈值”作为独立告警项，而不是等 FVD 离线评估。</p>\n<p>第二段是显存溢出与批抖动。显存峰值由同时在处理的块数与激活缓存共同决定，块过大时回退到更小分块——这条回退路径本身就是抖动源：分块尺寸改变会改变每块的时空注意力形状与重叠区比例，进而改变 VAE 拼接的接缝位置，同一请求在不同并发下可能走出不同的分块序列。工程上应把分块上限做成按分辨率与帧数档位预设的常量，而不是运行时自适应收缩；回退次数要作为容量指标上报，回退率上升意味着该档位的激活缓存预算已经不足，而非偶发。批大小受激活显存约束，长视频倾向小批分块流式处理，因此吞吐对批大小的敏感度远高于短请求场景，批调度器需要按“块”而非按“请求”计量占用。</p>\n<p>第三段是尾延迟与多样性损失。少步蒸馏把学生步数压到教师之下，蒸馏项 <span class=\"formula\">$$\\lambda\\sum_k\\|\\epsilon_\\theta^{(k)}-\\epsilon_{\\mathrm{tea}}^{(k)}\\|_2^2$$</span> 只约束中间噪声预测，不约束采样轨迹的分布宽度，因此低比特加少步叠加时，细节损失与运动多样性损失会同时出现且难以从单一指标区分。监控上应把“每块去噪时延、VAE 解码时延、量化裁剪比例、分块回退次数”四项做成同一条时间线，尾延迟异常时先看回退次数是否抬升，再看裁剪比例是否在尾块跳变。回滚策略按粒度分级：先回滚分块上限到上一档位，再回滚量化方案到更高比特或关闭时间一致性尺度学习，最后才回滚到全精度多步采样；由于材料未给出硬件档位与 SLO 实测，这套分级只能作为机制层面的默认顺序，实际阈值需按档位容量标定后固化。</p>\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-46\">四十六 · 口径先于数字：这份材料能支撑什么判断</h3>\n<p>Q-VDiT 的材料里没有可核验的定量表：没有给出数据集名称与规模，没有给出硬件档位、并行拓扑、批大小与分辨率组合，也没有 FVD、步数、显存峰值、端到端时延的任何数值。这意味着本部分的任务不是“读一张结果表”，而是先把评测口径的骨架搭出来，再判断哪些提升在什么条件下才可比。对工程读者而言，一份缺少数字的材料仍然有信息量——它至少暴露了作者选择在哪些维度上主张收益（低比特激活下的生成质量、少步采样的时延），以及回避了哪些维度（吞吐、功耗、SLO、长视频边界误差）。口径分析的价值就在于：把“主张的维度”翻译成“必须补齐的测量项”，并指出哪些跨论文比较从一开始就不成立。</p>\n<p>视频 DiT 推理的测量对象与 LLM 解码不同。LLM 的 TTFT/TPOT 建立在自回归逐 token 生成的线性结构上，而视频扩散的一次请求是“条件编码 → 多步去噪 → VAE 解码 → 流式输出”的流水线，去噪步数与时间块数共同决定前向次数。因此本部分采用的指标口径是：首块输出时延（对应 TTFT 的类比物，从请求进入到第一块解码结果可返回）、每块去噪时延（对应 TPOT 的类比物，衡量稳态推进速度）、整段完成时延、稳态吞吐（单位时间完成的请求数或帧数）、显存峰值、以及功耗或能耗每请求。这六项必须成组报告，单独报其中一项无法支撑容量规划。</p>\n<div class=\"formula\">$$\\text{整段时延}=T_{\\text{enc}}+N_{\\text{blk}}\\cdot\\left(\\frac{S}{S_{\\text{eff}}}\\cdot t_{\\text{step}}\\right)+N_{\\text{blk}}\\cdot t_{\\text{vae}},\\quad \\text{显存峰值}\\approx B_{\\text{blk}}\\cdot(A_{\\text{act}}+K_{\\text{cache}})+M_{\\text{w}}$$</div>\n<p>式中 $S$ 为教师步数、$S_{\\text{eff}}$ 为蒸馏后的学生步数，$t_{\\text{step}}$ 为单步前向时延，$N_{\\text{blk}}$ 为时间块数，$B_{\\text{blk}}$ 为同时在处理的块数，$A_{\\text{act}}$ 为单块激活缓存、$K_{\\text{cache}}$ 为块内注意力缓存、$M_{\\text{w}}$ 为权重占用。这个式子说明一件事：Q-VDiT 的两条主张分别落在不同的项上——步数蒸馏压缩的是 $S/S_{\\text{eff}}$ 这个乘数，低比特量化压缩的是 $t_{\\text{step}}$（通过张量核心算力密度）与 $A_{\\text{act}}$（通过激活位宽）。两者对时延的贡献是相乘关系，因此任何“联合方案比单独方案快多少”的表述，都必须固定另一条路径的取值，否则不可比。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-47\">四十七 · 硬件档位：Blackwell 上的低比特算子可用性决定基线</h3>\n<p>材料只说“按 Blackwell B200／GB200 NVL72 类张量核心假设低比特算子可用”，未给出部署档位。这句话在口径上意味着：Q-VDiT 的量化收益上限由 NVFP4／FP8 张量核心的算力密度决定，但其精度主张与这些算力无关，只与量化算子本身有关。工程上必须把两类测量分开：精度类测量（生成质量指标）应在固定硬件上做，因为量化误差与硬件无关；性能类测量（时延、吞吐、显存）必须绑定具体档位，因为 B200 单卡与 GB200 NVL72 机架在显存容量、NVLink 5 带宽与可用的并行拓扑上完全不同。把单卡分块流式的时延数字与机架级并行的数字放在同一张表里比较，是最常见的不可比来源。</p>\n<p>具体机制上，低比特激活量化在时空注意力输入处插入伪量化算子，权重走分组量化，激活走带尺度裁剪的量化：</p>\n<div class=\"formula\">$$\\hat{A}=\\mathrm{clip}\\left(\\frac{A}{s_t}\\right)\\cdot s_t,\\quad s_t=f(\\text{时间步},\\ \\text{块索引})$$</div>\n<p>尺度 $s_t$ 按时间步与块更新，这是压制跨帧离群值的关键，但材料未给出比特位宽与分组大小。位宽决定了这条路径能否真正落到 NVFP4 张量核心上：若激活位宽与权重位宽的组合不被硬件原生支持，则量化只带来显存带宽收益而不带来算力收益，此时 $t_{\\text{step}}$ 的下降幅度会显著小于预期。因此硬件档位的第一项口径是“量化方案是否映射到原生低比特 MMA”，第二项才是“映射后实测的单步时延”。材料对前者未表态，故任何声称的加速比都无法归因。</p>\n<p>代价侧的具体例子：假设单块 latent 的时空注意力激活为若干百 MB 量级，低比特化把激活位宽减半可将 $A_{\\text{act}}$ 压到约一半，从而允许 $B_{\\text{blk}}$ 翻倍或把块尺寸放大；但若分块过大触发溢出回退，系统会退到更小分块，此时块数 $N_{\\text{blk}}$ 增加、块间重叠区增多，VAE 解码拼接的重复计算上升，端到端时延反而变差。这是分块溢出失败模式的直接代价，也是显存峰值与吞吐之间的非单调关系。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-48\">四十八 · batch 与并发：视频请求的批维度不是标量</h3>\n<p>LLM 推理的 batch 是一个标量（并发序列数），视频扩散的批维度至少有三个：并发请求数、每请求的时间块数、以及块内是否再切空间维。材料明确“批大小受激活显存约束，长视频倾向小批分块流式处理；并发请求下按块调度”。这句话的口径含义是：Q-VDiT 的吞吐数字必须说明是按“请求/秒”还是按“帧/秒”，以及并发请求是否共享同一批权重、是否在块粒度上交错调度。两种调度策略的显存峰值模型不同——按请求整段调度时峰值由最长请求的整段激活决定，按块交错调度时峰值由同时在处理的块数 $B_{\\text{blk}}$ 决定，后者可以把峰值压平但引入块间切换开销。</p>\n<p>并发下的 SLO 口径同样要拆开：材料说“SLO 以首块输出时延与整段完成时延共同衡量”。首块时延由条件编码加第一块去噪加首块 VAE 解码构成，与并发数弱相关（只要显存不溢出）；整段完成时延则随并发数上升而显著劣化，因为块调度在竞争同一批张量核心与显存带宽。工程判断是：视频生成的容量规划应以“首块时延达标前提下的最大并发块数”为约束，而不是以平均吞吐为约束——用户对首帧的等待感知远强于对整段完成的感知。材料未给出这两个时延的任何数值，故容量标定只能停留在“按块大小与量化方案做标定”的层面。</p>\n<p>具体例子：若单请求被切成 $N_{\\text{blk}}$ 块、每块 $S_{\\text{eff}}$ 步，则单请求的前向次数为 $N_{\\text{blk}}\\cdot S_{\\text{eff}}$；并发 $C$ 个请求按块交错时，稳态下每块去噪时延近似不变而整段时延放大约 $C$ 倍（在算力饱和区）。这解释了为什么“吞吐提升”与“整段时延改善”在并发场景下经常方向相反，也解释了为什么只报吞吐的论文数字不能用于 SLO 承诺。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-49\">四十九 · 指标怎么读：四条不可比的提升</h3>\n<p>第一类不可比：量化收益与蒸馏收益混报。Q-VDiT 把时间一致性量化与步数蒸馏联合训练，损失为扩散去噪损失加教师中间步预测的蒸馏项：</p>\n<div class=\"formula\">$$\\mathcal{L}=\\mathcal{L}_{\\mathrm{diff}}+\\lambda\\sum_{k}\\left\\|\\epsilon_\\theta^{(k)}(x_t)-\\epsilon_{\\mathrm{tea}}^{(k)}(x_t)\\right\\|_2^2$$</div>\n<p>材料未给出 $\\lambda$、教师步数、学生步数。若论文报告“相对全精度多步基线”的提升，则该提升同时包含少步带来的质量变化与低比特带来的质量变化，无法拆分。可比的口径要求四条曲线：全精度多步、全精度少步、低比特多步、低比特少步，缺一条则归因不成立。</p>\n<p>第二类不可比：分辨率与帧数不同。材料说“分辨率与帧数变化会改变时空注意力激活规模，需按档位设定分块上限”。时空注意力的激活规模随帧数与分辨率近似二次增长（时间维与空间维各自的序列长度相乘），因此在一个分辨率下测得的显存峰值与吞吐不能外推到另一分辨率。第三类不可比：分块重叠比例不同。重叠区用于 VAE 解码拼接以抑制接缝，重叠比例材料未给出；重叠越大，重复解码计算越多，整段时延越高，但接缝质量越好——这是一个显式的质量-时延折衷参数，跨论文比较时必须对齐。第四类不可比：是否包含 VAE 解码。材料明确“VAE 解码与去噪阶段分离”，若一方报告的是纯去噪时延、另一方是端到端含解码时延，两者差距可达数倍，因为高分辨率 VAE 解码本身是显存带宽密集型操作。</p>\n<table class=\"mini\"><thead><tr><th>报告项</th><th>必须绑定的口径</th><th>缺失时的后果</th></tr></thead><tbody><tr><td>生成质量指标</td><td>分辨率、帧数、教师/学生步数、比特位宽</td><td>无法区分量化误差与少步误差</td></tr><tr><td>首块时延</td><td>硬件档位、块大小、是否含首块 VAE 解码</td><td>与 LLM 的 TTFT 误比</td></tr><tr><td>整段完成时延</td><td>并发数、块调度策略、重叠比例</td><td>吞吐与时延方向混淆</td></tr><tr><td>显存峰值</td><td>同时在处理的块数、激活缓存预算、是否含权重</td><td>容量规划失真</td></tr><tr><td>功耗/能耗</td><td>档位、利用率、是否含 VAE 阶段</td><td>材料完全缺失，无法评估</td></tr></tbody></table>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-50\">五十 · 长视频与分块边界：误差累积的测量缺口</h3>\n<p>材料承认“低比特激活在时空注意力输入处引入量化误差，长视频下误差沿时间维累积，材料未给出误差上界或补偿机制”，且“分块重叠区的量化误差累积缺少失败模式说明”。这是口径上最值得警惕的一处：时间一致性量化本意是让尺度 $s_t$ 跨帧平滑，但尺度按块更新意味着块边界处尺度发生跳变，若相邻块的激活分布差异大，边界帧的量化误差会高于块内帧。测量上应报告“按帧位置的误差分布”而非单一平均值——若误差在块边界处出现尖峰，则长视频的整段质量指标会被块内帧稀释而显得乐观。</p>\n<p>代价侧：块边界误差的补偿通常需要增大重叠区或引入跨块尺度平滑，前者增加 VAE 解码重复计算（时延上升），后者需要在去噪阶段保留上一块的尺度状态（显存与依赖链上升，破坏块间并行）。材料未给出任何一种，故长视频场景的部署判断只能定性：块数越多、边界越多，风险越高；分辨率越高，单块激活越大，越容易触发溢出回退，而回退会改变块划分，进而改变边界位置——这使误差分布随负载动态变化，难以用固定标定覆盖。</p>\n<p>具体例子：一条长视频被切成 $N_{\\text{blk}}$ 块，若每块边界引入可观的量化偏差，则整段误差近似随 $N_{\\text{blk}}$ 线性累积（在无补偿机制时），而块内误差不随块数增长。这意味着“增加分块数以降低显存峰值”与“保持时间一致性”之间存在直接冲突，是 Q-VDiT 类分块流式方案在长视频上的结构性代价，也是材料未给出失败模式分析所掩盖的最大风险点。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-51\">五十一 · 落地标定的最小测量集</h3>\n<p>基于以上口径，工程落地时应建立一组最小测量集，且每一项都必须绑定档位与负载参数：在目标 Blackwell 档位上，固定分辨率与帧数，扫块大小与并发块数两个维度，记录首块时延、每块去噪时延、整段完成时延、显存峰值、溢出回退次数、以及按帧位置的量化误差分布；再在固定块大小下扫比特位宽组合，确认量化方案是否映射到原生低比特 MMA，若未映射则性能收益只来自带宽而非算力。功耗项材料完全缺失，只能在实际机架上补测，且必须区分去噪阶段与 VAE 解码阶段的能耗占比——后者是带宽密集型，前者在低比特下才可能转为算力密集型。</p>\n<p>判断准则落在一条具体的机制上：Q-VDiT 的收益是“步数乘数”与“单步时延乘数”的乘积，而这两个乘数分别被蒸馏调度与量化位宽独立控制；只要报告中没有把这两个乘数拆开、没有固定分块重叠比例与是否含 VAE 解码、没有给出块边界误差分布，任何跨方案的数字比较都不成立。可复核的最小主张因此只能是定性的：在原生低比特 MMA 可用、块大小未触发溢出回退、重叠比例固定的条件下，联合方案相对“仅量化”或“仅蒸馏”应在整段时延上体现为两个乘数的乘积效应，而在质量上需要四条曲线才能归因。材料未提供这些，容量标定必须从自家负载的块级测量开始，而不是从论文的汇总数字开始。</p>\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-52\">五十二 · 迁移到非视频 DiT 时的量化侧改写</h3>\n<p>Q-VDiT 的量化算子不是通用低比特量化器，它的尺度更新依赖“时间维与块”这两个索引：<span class=\"formula\">$$s_t$$</span> 随去噪步与时间块变化，本质是把跨帧离群值的统计量摊到时间轴上。迁到图像 DiT（无时间维）时，这个先验直接失效，尺度只能退化为按去噪步与空间窗口更新，时间一致性约束项必须删掉或替换为空间局部一致性——否则可学习尺度会在无时间维的张量上失去约束，训练时尺度漂移、推理时裁剪过激。迁到语言模型或音频 DiT 时问题更尖锐：语言激活的离群值集中在少数通道（channel-wise outlier），而非时间维；把时间维平滑先验套上去等于给通道维做错误的正则，量化误差反而放大。工程判断是：这套方案的迁移成本主要不在伪量化算子本身（那是可移植的），而在“离群值沿哪个轴累积”的先验假设；换领域前必须先做一轮激活分布剖面，确认离群轴与时间轴是否重合，不重合就得重写尺度更新规则与正则项。</p>\n<p>代价层面：图像 DiT 上删去时间维后，尺度参数量下降、校准开销降低，但失去时间平滑后 W4A4 的精度回落幅度不可预估，需要用全精度教师做逐层敏感度扫描来定哪些层保留 8 bit。视频侧则相反，时间维越长，尺度需要覆盖的块越多，校准集的帧数需求线性上升。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-53\">五十三 · 蒸馏侧的迁移边界：教师轨迹依赖采样器</h3>\n<p>蒸馏项 <span class=\"formula\">$$\\lambda\\sum_k\\|\\epsilon_\\theta^{(k)}(x_t)-\\epsilon_{\\mathrm{tea}}^{(k)}(x_t)\\|_2^2$$</span> 的监督信号是教师多步采样的中间噪声预测。这意味着学生继承的不只是“少步”，而是教师所用采样器（ scheduler 与 solver）的轨迹形状。迁到另一个模型时，如果教师换用不同采样器或不同噪声 schedule，中间步的 <span class=\"formula\">$$x_t$$</span> 分布与噪声预测目标都会变，蒸馏项需要重新对齐 k 的索引映射，否则学生学到的是错位的轨迹。迁到非扩散生成范式（如自回归视频生成、流匹配）时，这个蒸馏项的形式不再成立：流匹配的监督是速度场而非噪声预测，需要把 <span class=\"formula\">$$\\epsilon$$</span> 换成 <span class=\"formula\">$$v$$</span> 并重推权重 λ 的量纲。工程上可行的做法是保留“教师中间潜变量作监督”的骨架，替换预测目标与索引映射，而不是照搬损失函数。</p>\n<p>系统代价：蒸馏训练阶段需要教师多步前向并缓存中间潜变量，显存与算力开销随教师步数线性增长；这部分只在离线发生，不影响推理 SLO，但决定了学生能否在目标模型上复现。推理侧少步调度一旦确定，学生的步数表就与教师解耦，迁移时真正要重做的是这张步数表与 λ 的标定，而非网络结构。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-54\">五十四 · 分块流式解码的适用上限</h3>\n<p>推理按时间块切分 latent、块间保留重叠区供 VAE 解码拼接，显存峰值由同时在处理的块数与激活缓存决定。这个机制的上限由两个量夹住：块内时空注意力的激活规模随分辨率与帧数增长，重叠区比例决定拼接质量但也决定重复计算量。设块数为 <span class=\"formula\">$$N_b$$</span>、重叠帧比例为 <span class=\"formula\">$$r$$</span>，则有效计算量约为 <span class=\"formula\">$$(1+r)\\cdot N_b$$</span> 块当量，重叠越大接缝越稳、吞吐越低。当分辨率升到时空注意力激活超出单卡预算时，块必须缩小，块数上升，重叠区的绝对帧数被压缩，接缝风险上升——这是该方案在超高分辨率长视频上的结构性上限，不是调参能绕过的。</p>\n<p>迁到需要全局时间一致性的场景（长镜头、跨块运动连续性要求高的编辑类任务）时，块间重叠只能缓解接缝，无法保证跨块的运动轨迹连贯；这类场景要么放弃分块、接受单块显存溢出回退，要么引入跨块状态传递（把上一块的末端 latent 作为下一块的条件），而后者在材料中并未设计。判断：分块流式适合“可接受块级独立生成”的批量视频产出，不适合强全局一致性的单条长视频。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-55\">五十五 · 与批调度、分离式部署的不兼容点</h3>\n<p>材料明确该方法未给出批调度、投机解码或分离式预填/解码的机制设计。这不是遗漏，而是与分块流式的结构冲突：连续批处理要求请求在 token/步粒度上交错推进，而分块流式按块串行、块内全步推进，批内不同请求的块边界不对齐，交错调度会打乱块间重叠区的拼接顺序。迁到 vLLM/SGLang 类连续批处理框架时，需要把“块”提升为调度单元，按块做准入与释放，这实际上是把连续批处理降级为块级批处理，吞吐收益让位于显存可控。</p>\n<p>分离式预填/解码在扩散模型上没有直接对应物（没有 KV cache 的预填/解码二分），但可以把条件编码与首块去噪视为“预填”、后续块视为“解码”，做跨节点流水；代价是块间重叠区需要跨节点传输，NVLink 域内尚可，跨节点则通信量随重叠比例上升。容量判断：单卡分块流式是这套方案的原生形态，跨卡切分必须按 latent 时间维评估通信代价，切分点应落在块边界而非块内。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-56\">五十六 · 规模上限与判断准则</h3>\n<p>把三条边界合起来看，规模上限由三个约束的交集决定：量化侧的时间一致性先验要求离群轴与时间轴重合，蒸馏侧要求教师轨迹可对齐，分块侧要求块内激活不溢出且重叠区可接受。三者任一不满足，方案就要改写而非调参。落地前的判断准则可以写成一张检查表：激活离群轴是否沿时间维；教师采样器是否可在目标模型上复现中间步；目标分辨率下块内时空注意力激活是否落在单卡预算内；跨块一致性要求是否允许块级独立生成。四项全过，方案可原样迁移；任一项不过，按对应节改写。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>需改写项</th><th>主要代价</th></tr></thead><tbody><tr><td>图像 DiT</td><td>删时间维尺度更新与正则</td><td>精度回落需逐层敏感度扫描</td></tr><tr><td>流匹配/自回归</td><td>蒸馏目标由 ε 换为 v 或隐状态</td><td>教师轨迹缓存显存上升</td></tr><tr><td>超高分辨率长视频</td><td>块缩小、重叠比例重标定</td><td>有效计算量随重叠线性上升</td></tr><tr><td>连续批处理框架</td><td>块提升为调度单元</td><td>吞吐让位于显存可控</td></tr></tbody></table>\n<p>最后落在工程判断上：Q-VDiT 的可迁移内核是“把量化误差校正与步数蒸馏放进同一条推理链、以块为显存控制单元”，而不是那组具体公式；迁到新模型时先验证离群轴与教师轨迹这两件事，再决定是否保留时间一致性约束与分块重叠，其余部分按目标领域的激活分布重写。材料未给出硬件档位与 SLO 实测，任何容量数字都必须在目标档位上重新标定，不能从机制层面外推。</p>\n\n<h3 id=\"paper-q-vdit-towards-accurate-quantization-2025-sec-57\">五十七 · 迁移与边界：哪些结构能吃下这套方案，哪些只会放大它的误差</h3>\n<p>这套方案的可迁移性，取决于目标模型是否具备两个前提：激活分布沿一条有序维度（时间、序列位置、模态轴）连续变化，且推理本身已经是多步迭代采样。视频 DiT 同时满足这两条，所以时间一致性量化尺度 <span class=\"formula\">$$s_t$$</span> 有明确的物理含义——它对应跨帧激活统计的漂移。迁到图像 DiT，时间维退化为单帧，时间一致性约束失去约束对象，只剩分组权重量化与步数蒸馏在起作用；此时量化收益主要来自权重侧，激活侧的低比特裁剪反而更容易在单帧高频纹理上产生结构性偏差。迁到自回归语言模型则更不适用：解码是逐 token 串行、每步只前向一次，没有“多步教师轨迹”可供蒸馏，蒸馏项 <span class=\"formula\">$$\\lambda\\sum_k\\|\\epsilon_\\theta^{(k)}-\\epsilon_{\\mathrm{tea}}^{(k)}\\|_2^2$$</span> 直接失效，只剩量化感知训练这一半，而语言模型的激活离群值集中在少数通道而非时间维，需要的是通道级尺度而非时间平滑先验。判断很直接：这套方法的迁移半径是“迭代式生成 + 有序激活维”，越出这个范围，两个核心组件至少有一个空转。</p>\n<p>规模上限首先撞在分块溢出这条失败路径上。显存峰值由同时在处理的块数与激活缓存共同决定，块过大即回退到更小分块——回退本身不是免费的，它改变块边界，而块边界正是时间一致性尺度更新的锚点。块被切碎后，重叠区占比上升，同一段 latent 被重复去噪与重复解码，有效算力被重叠比例稀释。设单块去噪时延为 <span class=\"formula\">$$T_b$$</span>、重叠比例为 <span class=\"formula\">$$r$$</span>、总块数为 <span class=\"formula\">$$N$$</span>，端到端去噪时延近似为 <span class=\"formula\">$$T_{\\text{total}}\\approx N\\cdot T_b\\cdot(1+r)$$</span>，而 <span class=\"formula\">$$r$$</span> 随块变小而单调上升。这意味着分辨率与帧数上升时，系统不是平滑变慢，而是在某个块大小阈值处出现时延与显存的联合跳变。Blackwell 的 NVFP4／FP8 张量核心提升了算力密度，但分块流式解码的瓶颈往往不在算力而在激活带宽与 VAE 解码的峰值占用，低比特压缩的是前者，压不住后者。</p>\n<p>误差侧的边界更值得警惕。低比特激活在时空注意力输入处引入的量化误差沿时间维累积，材料未给出误差上界或补偿机制；而少步蒸馏把教师的多步轨迹压成少步调度，两者叠加时误差不是相加而是耦合——量化噪声改变了学生每步的输入分布，蒸馏监督却按教师的干净轨迹给出目标，学生被要求用一个带噪的输入去拟合一个无噪的输出。长视频场景下这条耦合链最长，分块重叠区的量化误差累积缺少失败模式分析，风险最高。可迁移到长序列视频时，必须先回答一个问题：重叠区是否共享同一套量化尺度？共享则跨块一致但块内统计失配，不共享则接缝处出现尺度跳变。材料没有给出这个设计选择，落地时它就是一个必须自行标定的自由参数。</p>\n<p>系统代价上还有一处结构性缺口：该方法面向推理侧低比特少步部署，未给出批调度、投机解码或分离式预填／解码的机制设计。迁到需要连续批处理与多请求并发的服务场景，分块流式解码与批调度会互相挤压——块调度以显存峰值为约束，批调度以吞吐为目标，两者对块大小的最优解不一致。容量规划只能停留在机制层面：按分块上限设定并发上限，按重叠比例折算有效吞吐，按块溢出回退次数设告警阈值。迁到 GB200 NVL72 这类多卡拓扑时，跨卡切分需按 latent 时间维评估通信代价，而材料未给出并行拓扑，任何跨卡扩展的收益判断都缺乏依据。结论是工程性的：这套方案适合单卡、分块流式、以首块输出时延为 SLO 主指标的部署形态；一旦进入高并发批服务或跨卡长视频切分，需要重做的不是量化算子，而是块调度与尺度一致性这两层。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Q-VDiT: Towards Accurate </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Quantization a…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Q-VDiT: Towards Accurat… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>视频生成基准数据集（材料未给出具体名称与规模）</td></tr><tr><td>基线</td><td>全精度多步视频 DiT 采样、常规低比特量化视频 DiT</td></tr><tr><td>主要结果</td><td>材料未给出可核验的定量指标；论文主张在低比特激活量化下相对常规量化基线改善…</td></tr><tr><td>消融</td><td>材料未给出消融表；从机制上看应关注量化尺度学习、时间一致性约束与蒸馏权重的…</td></tr><tr><td>局限</td><td>材料未给出硬件档位、批大小与分辨率下的实测吞吐；低比特量化在长视频分块边界…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-q-vdit-towards-accurate-quantization-2025 · 共 9 个片段</p>\n";break;}}})();
